-- Catalogue additions for training blocks (3 exercises), approved 2026-10-03.
-- Generated by scripts/catalogue-v2-seed.py from docs/fitness/approved/catalogue-v2/*.json
-- 227 exercises. Re-run the script instead of editing by hand.
insert into public.exercises (id, name_en, name_es, body_region, primary_muscle, primary_muscles,
  secondary_muscles, equipment, movement_pattern, mechanic, laterality, posture_tips, aliases, is_active) values
  ('ab-wheel-rollout', 'Ab Wheel Rollout', 'Rueda abdominal', 'Core', 'Abs', array['Abs']::text[], array['Lats', 'Obliques', 'Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Kneel on a mat and hold the wheel under your shoulders with straight arms.', 'Keep your pelvis tucked and your ribs down throughout the rollout.', 'Roll forward as far as you can control, then pull back using your abs.', 'Don''t let your lower back sag as the wheel moves away from your knees.', 'Increase your range gradually; start with short rollouts.']::text[], '{}'::text[], true),
  ('back-extension-single-leg', 'Back Extension (Single-Leg)', 'Hiperextensión (a una pierna)', 'Glutes', 'Glutes', array['Glutes', 'Hamstrings']::text[], array['Lower Back']::text[], 'bodyweight', 'hinge', 'compound', 'unilateral', array['Set up on the 45-degree bench with one foot locked in and the other leg free behind you.', 'Keep your pelvis level without letting the free hip drop or rotate.', 'Lower by hinging at your working hip, then rise by squeezing that side''s glute.', 'Don''t twist your torso to make up for a weaker side.', 'Master the two-leg version before progressing to this one.']::text[], '{}'::text[], true),
  ('back-squat', 'Barbell Back Squat', 'Sentadilla trasera con barra', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Lower Back']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Set the bar on your upper traps, feet shoulder-width apart and toes turned out slightly.', 'Keep your chest up and spine neutral, with your knees tracking over your toes.', 'Descend under control to at least parallel, then drive up by pushing the floor away with your whole foot.', 'Don''t let your knees cave inward as you drive out of the bottom.', 'Squat inside a rack with the safety pins set just below your bottom position.']::text[], '{}'::text[], true),
  ('band-assisted-pull-up', 'Band Assisted Pull-Up', 'Dominadas asistidas con banda', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'band', 'pull vertical', 'compound', 'bilateral', array['Loop the band over the bar and place a knee or foot in it before hanging with an overhand grip.', 'Keep your body in a straight line and your core tight so the band doesn''t swing you.', 'Pull until your chin is over the bar and lower under control, without letting the band snap you up.', 'Don''t rely on a thick band forever; switch to a lighter one once you hit your target reps.', 'Check the band for nicks and make sure it''s securely looped before every set.']::text[], '{}'::text[], true),
  ('band-lateral-walk', 'Band Lateral Walk', 'Caminata lateral con banda', 'Glutes', 'Abductors', array['Abductors', 'Glutes']::text[], '{}'::text[], 'band', 'isolation', 'isolation', 'bilateral', array['Loop a band around your knees or ankles and sit into a slight hip and knee bend.', 'Keep tension on the band and hold your half-squat position on every step.', 'Take short, controlled side steps without bringing your feet fully together.', 'Don''t sway your torso side to side with each step.', 'Check the band for cracks or tears before using it.']::text[], '{}'::text[], true),
  ('band-pull-apart', 'Band Pull-Apart', 'Separaciones con banda elástica', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'band', 'isolation', 'isolation', 'bilateral', array['Hold the band in front of your chest, arms straight and hands shoulder-width apart.', 'Keep your ribs down and your shoulders away from your ears.', 'Pull your hands apart, bringing the band to your chest, then return without losing tension.', 'Don''t bend your elbows to make it easier.', 'Inspect the band before use and throw it out if it has cracks or nicks.']::text[], '{}'::text[], true),
  ('band-straight-arm-pulldown', 'Band Straight-Arm Pulldown', 'Jalón con brazos rectos con banda', 'Back', 'Lats', array['Lats']::text[], array['Triceps', 'Rear Delts']::text[], 'band', 'isolation', 'isolation', 'bilateral', array['Anchor the band overhead, grab it with both hands and step back until there''s tension.', 'Keep your arms straight, chest up and a slight hip hinge.', 'Sweep your hands down in an arc to your hips, then return slowly to shoulder height.', 'Don''t shrug as the band pulls your arms back up.', 'Check the anchor and the band''s condition; if it slips it can snap back at you.']::text[], '{}'::text[], true),
  ('barbell-bench-press', 'Barbell Bench Press', 'Press de banca con barra', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Lie with your eyes under the bar, feet planted, and grip slightly wider than shoulder width.', 'Pinch your shoulder blades together and keep a slight arch, with glutes and head on the bench.', 'Lower the bar under control to your lower chest, then press up and slightly back.', 'Don''t flare your elbows to 90 degrees; keep them about 45-70 degrees from your torso on the way down.', 'Use safety arms or a spotter whenever you train close to failure.']::text[], array['bb-bench-press']::text[], true),
  ('barbell-bent-over-row', 'Barbell Bent-Over Row', 'Remo inclinado con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Grip the bar overhand slightly wider than shoulders, knees soft, and hinge your torso to about 45 degrees.', 'Keep your back neutral and neck in line, eyes on the floor slightly ahead of you.', 'Row the bar to your navel while squeezing your shoulder blades, then lower to straight arms without moving.', 'Don''t stand up on each rep to heave the bar up with momentum.', 'If you can''t hold a neutral back, drop the load before continuing.']::text[], '{}'::text[], true),
  ('barbell-box-squat', 'Barbell Box Squat', 'Sentadilla a cajón con barra', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors', 'Lower Back']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Place a box behind you at parallel height and take a slightly wider stance than usual.', 'Sit your hips back, keeping your shins near vertical and your chest up.', 'Sit softly onto the box, pause briefly while staying tight, then drive up hard.', 'Don''t crash onto the box or rock backward to build momentum.', 'Check that the box is stable and won''t slide before you start.']::text[], '{}'::text[], true),
  ('barbell-curl', 'Barbell Curl', 'Curl con barra', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Grip the bar underhand at shoulder width with your arms fully extended.', 'Squeeze your glutes and brace your abs so your torso doesn''t arch backward.', 'Curl the bar in an arc to your chest without moving your elbows, then lower over 2-3 seconds.', 'Don''t hip-thrust the bar to get it moving off the bottom.', 'If a straight bar strains your wrists, switch to an EZ-bar.']::text[], '{}'::text[], true),
  ('barbell-deadlift', 'Barbell Deadlift', 'Peso muerto con barra', 'Legs', 'Glutes', array['Glutes', 'Hamstrings']::text[], array['Lower Back', 'Quads', 'Traps', 'Forearms']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Set your feet hip-width with the bar over midfoot and grip it just outside your legs.', 'Keep your spine neutral and the bar dragging close to your body all the way up.', 'Push the floor away, lock out your hips at the top, and slide the bar down your thighs to lower.', 'Don''t let your hips shoot up before the bar moves and round your back.', 'Brace before every rep and reset the bar on the floor whenever your position slips.']::text[], '{}'::text[], true),
  ('barbell-deadlift-sumo', 'Barbell Deadlift (Sumo)', 'Peso muerto con barra (sumo)', 'Legs', 'Glutes', array['Glutes', 'Adductors']::text[], array['Quads', 'Hamstrings', 'Lower Back']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Set your feet well outside your shoulders, toes out, and grip the bar between your legs.', 'Keep your chest up and push your knees out over your toes.', 'Push the floor apart to break the bar off the ground and finish by driving your hips to the bar.', 'Don''t let your knees cave in as the bar leaves the floor.', 'Warm up your adductors with light sets before loading the bar.']::text[], '{}'::text[], true),
  ('barbell-front-squat', 'Barbell Front Squat', 'Sentadilla frontal con barra', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Upper Back', 'Abs']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Rack the bar on your front delts with elbows high, using a clean grip or crossed-arm grip.', 'Keep your elbows up and your torso upright the whole way down.', 'Sit down between your legs to just below parallel, then lead the drive up with your elbows.', 'Don''t let your elbows drop, or the bar will roll forward off your shoulders.', 'If you lose the bar, push it forward and step back; always set the rack safeties.']::text[], '{}'::text[], true),
  ('barbell-glute-bridge', 'Barbell Glute Bridge', 'Puente de glúteo con barra', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Lie on the floor with the padded bar over your hips and your feet close to your glutes.', 'Keep your upper back on the floor and your knees hip-width apart.', 'Drive your hips to full extension, hold for a second, and lower until you brush the floor.', 'Don''t let your heels lift off the floor as you drive up.', 'Use full-size plates so you can roll the bar over your legs to set up.']::text[], '{}'::text[], true),
  ('barbell-good-morning', 'Barbell Good Morning', 'Buenos días con barra', 'Legs', 'Hamstrings', array['Hamstrings', 'Lower Back']::text[], array['Glutes']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Set the bar on your traps as for a squat, with your feet hip-width apart.', 'Keep your spine neutral and a slight bend in your knees throughout the hinge.', 'Push your hips back until your torso is nearly parallel, then stand up squeezing your glutes.', 'Don''t lower your chest by rounding your back instead of hinging at the hips.', 'Start light and work inside the rack with the safeties set.']::text[], '{}'::text[], true),
  ('barbell-hip-thrust', 'Barbell Hip Thrust', 'Hip thrust con barra', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Quads']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Rest your lower shoulder blades on a bench and set the padded bar over your hips.', 'Keep your chin tucked and your ribs down as you drive up.', 'Push through your heels until knees, hips, and shoulders line up, pause, then lower slowly.', 'Don''t finish by arching your lower back instead of extending your hips.', 'Use a bar pad and a fixed bench that won''t slide.']::text[], '{}'::text[], true),
  ('barbell-jm-press', 'Barbell JM Press', 'Press JM con barra', 'Arms', 'Triceps', array['Triceps']::text[], array['Chest', 'Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Lie on a flat bench with a close grip, slightly narrower than shoulder width.', 'Keep your elbows pointing toward your feet and your shoulder blades set on the bench.', 'Lower the bar toward your upper chest or chin by bending your elbows, then press back up.', 'Don''t turn it into a bench press; the bar shouldn''t touch your chest.', 'Use safety arms or a spotter; the bar comes down close to your face.']::text[], '{}'::text[], true),
  ('barbell-lunge-reverse', 'Barbell Lunge (Reverse)', 'Zancada con barra (hacia atrás)', 'Legs', 'Glutes', array['Glutes', 'Quads']::text[], array['Hamstrings', 'Adductors', 'Abs']::text[], 'barbell', 'lunge', 'compound', 'unilateral', array['Unrack the bar onto your traps and take two steps back to clear space.', 'Brace your core and keep the bar level, without tipping it to one side.', 'Step back, drop straight down, then drive through your front foot to return.', 'Don''t rush; start every rep with your feet together and stable.', 'Work inside the rack with the safeties set in case you lose your balance.']::text[], '{}'::text[], true),
  ('barbell-meadows-row', 'Barbell Meadows Row', 'Remo Meadows con barra', 'Back', 'Lats', array['Lats', 'Upper Back']::text[], array['Rear Delts', 'Biceps', 'Forearms']::text[], 'barbell', 'pull horizontal', 'compound', 'unilateral', array['Stand perpendicular to the anchored bar, grip the end overhand and rest your free forearm on your knee.', 'Keep your hips high, torso hinged and back neutral without rotating.', 'Row the end of the bar toward your hip with the elbow flared, then lower until your lat stretches.', 'Don''t twist your torso open to move the load; keep rotation minimal.', 'Use smaller plates for more range of motion and anchor the bar securely before you start.']::text[], '{}'::text[], true),
  ('barbell-overhead-press', 'Barbell Overhead Press (Standing)', 'Press militar con barra (de pie)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps', 'Upper Chest', 'Abs']::text[], 'barbell', 'push vertical', 'compound', 'bilateral', array['Unrack the bar at collarbone height with a grip slightly wider than your shoulders.', 'Squeeze your glutes and abs to keep your ribs down and your spine neutral.', 'Press the bar straight up, push your head through at the top, and lower to your collarbones.', 'Don''t lean back so far that it becomes an incline press.', 'Set the rack hooks at chest height so you can unrack and rerack the bar safely.']::text[], '{}'::text[], true),
  ('barbell-overhead-press-seated', 'Barbell Overhead Press (Seated)', 'Press militar con barra (sentado)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'barbell', 'push vertical', 'compound', 'bilateral', array['Sit on an upright bench under the racked bar with your feet planted.', 'Keep your back against the pad and your head neutral.', 'Lower the bar in front of your face to chin level, then press until your arms are straight.', 'Don''t lower the bar behind your neck.', 'Set the hooks so you can unrack the bar without fully extending your arms to reach it.']::text[], '{}'::text[], true),
  ('barbell-pendlay-row', 'Barbell Pendlay Row', 'Remo Pendlay con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Set up with the bar on the floor over midfoot and your torso nearly parallel to the ground.', 'Keep your back flat and hips high, holding the same torso angle from rep to rep.', 'Row the bar explosively to your stomach and return it to the floor each rep, coming to a dead stop.', 'Don''t lift your torso to help the bar up; if you need to, the load is too heavy.', 'Set the bar down under control rather than dropping it, to protect your back and the equipment.']::text[], '{}'::text[], true),
  ('barbell-power-clean', 'Barbell Power Clean', 'Cargada de potencia con barra', 'Full Body', 'Glutes', array['Glutes', 'Quads']::text[], array['Hamstrings', 'Traps', 'Upper Back', 'Lower Back']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Set up with the bar over your midfoot, feet hip-width, grip just outside your legs.', 'Keep a neutral spine and the bar close to your body through the entire pull.', 'Drive your hips and knees to full extension and catch the bar on your shoulders, elbows forward.', 'Don''t pull with your arms before your hips have fully extended.', 'Learn the lift light or with a coach, and use bumper plates that can be dropped.']::text[], '{}'::text[], true),
  ('barbell-reverse-curl', 'Barbell Reverse Curl', 'Curl inverso con barra', 'Arms', 'Forearms', array['Forearms', 'Biceps']::text[], '{}'::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Grip the bar overhand at shoulder width with your arms fully extended.', 'Keep your wrists straight and in line with your forearms throughout.', 'Curl the bar up to your chest by bending your elbows, then lower it slowly.', 'Don''t let your wrists bend down as fatigue sets in.', 'Use less weight than a regular curl; the overhand grip limits how much you can handle safely.']::text[], '{}'::text[], true),
  ('barbell-reverse-wrist-curl', 'Barbell Reverse Wrist Curl', 'Curl de muñeca inverso con barra', 'Arms', 'Forearms', array['Forearms']::text[], '{}'::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Rest your forearms on your thighs or a bench, palms down, with your wrists over the edge.', 'Keep your forearms glued to the support and your fingers wrapped firmly around the bar.', 'Raise the backs of your hands as high as possible, then lower slowly into the stretch.', 'Don''t move your elbows or swing the bar to gain range.', 'Start very light; your forearm extensors fatigue quickly.']::text[], '{}'::text[], true),
  ('barbell-seal-row', 'Barbell Seal Row', 'Remo foca con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Lie face down on a high flat bench with the bar beneath you and your arms hanging straight.', 'Keep your chest and hips on the bench and your head in line with your torso.', 'Row the bar until it touches the underside of the bench, then lower slowly to full extension.', 'Don''t lift your chest off the bench to gain range; you lose support and tension.', 'Make sure the bench is stable on boxes or supports before you lie on it.']::text[], '{}'::text[], true),
  ('barbell-shrug', 'Barbell Shrug', 'Encogimientos con barra', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Take the bar from a rack at thigh height with a shoulder-width overhand grip.', 'Keep your arms straight, chest up and chin neutral, without looking up.', 'Raise your shoulders straight up toward your ears, hold for a second and lower them fully.', 'Don''t roll your shoulders in circles; the movement is straight up and down.', 'Unrack the bar from mid-thigh height instead of lifting it off the floor.']::text[], '{}'::text[], true),
  ('barbell-stiff-leg-deadlift', 'Barbell Stiff-Leg Deadlift', 'Peso muerto con piernas rígidas con barra', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Glutes', 'Lower Back', 'Forearms']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Stand with the bar over midfoot and your legs nearly straight but not locked.', 'Keep your spine neutral and your knees nearly straight throughout.', 'Lower the bar close to your legs to the floor or your limit, then stand by extending your hips.', 'Don''t pull with a rounded back just to reach the floor.', 'Use standard-size plates, or raise the bar if you can''t reach the floor with good form.']::text[], '{}'::text[], true),
  ('barbell-t-bar-row', 'Barbell T-Bar Row', 'Remo en T con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Straddle the anchored bar with a V-handle under the plates and your knees bent.', 'Keep your torso at about 45 degrees and your back neutral throughout the pull.', 'Row the handle to your lower chest driving your elbows back, then lower until your arms are straight.', 'Don''t load big plates that shorten your range or force you to swing.', 'Secure the end of the bar in a landmine or corner so it can''t slide.']::text[], '{}'::text[], true),
  ('barbell-upright-row', 'Barbell Upright Row', 'Remo al mentón con barra', 'Shoulders', 'Side Delts', array['Side Delts']::text[], array['Traps', 'Front Delts']::text[], 'barbell', 'pull vertical', 'compound', 'bilateral', array['Hold the bar in front of your thighs with hands slightly wider than shoulder width.', 'Keep your torso upright and the bar close to your body.', 'Lift the bar by leading with your elbows to your lower chest, then lower slowly.', 'Don''t pull the bar all the way to your chin with a narrow grip.', 'Stop at chest height if you feel discomfort at the top of your shoulder.']::text[], '{}'::text[], true),
  ('barbell-wrist-curl', 'Barbell Wrist Curl', 'Curl de muñeca con barra', 'Arms', 'Forearms', array['Forearms']::text[], '{}'::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Sit with your forearms on your thighs or a bench, palms up.', 'Keep your forearms fixed with only your wrists hanging over the edge.', 'Let the bar roll down to your fingertips, then curl your wrists up as high as you can.', 'Don''t lift your forearms or use your biceps to move the bar.', 'Stick to moderate weight and high reps to look after your wrists.']::text[], '{}'::text[], true),
  ('bb-bent-over-reverse-grip-rows', 'Barbell Bent-Over Row (Underhand Grip)', 'Remo inclinado con barra (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Grip the bar shoulder-width with palms facing forward and hinge at the hips.', 'Keep your torso angled and locked, core braced and the bar close to your thighs.', 'Row the bar to your lower abs, driving your elbows back and close to your body.', 'Don''t flex your wrists or turn the row into a biceps curl.', 'Lift the bar off the floor with a neutral back and your legs, never with a rounded back.']::text[], '{}'::text[], true),
  ('bird-dog', 'Bird Dog', 'Perro de caza (bird dog)', 'Core', 'Abs', array['Abs', 'Lower Back']::text[], array['Glutes', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Get on all fours with hands under shoulders and knees under hips.', 'Keep your back flat and pelvis level, as if balancing a glass on it.', 'Reach the opposite arm and leg out to horizontal, pause, and return slowly.', 'Don''t arch your lower back or rotate your hips as your leg lifts.', 'Move slowly and deliberately; stability matters more than height.']::text[], '{}'::text[], true),
  ('bodyweight-squat', 'Bodyweight Squat', 'Sentadilla con peso corporal', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'bodyweight', 'squat', 'compound', 'bilateral', array['Stand with feet shoulder-width apart and arms reaching forward for balance.', 'Keep your back straight and your weight spread evenly between heel and forefoot.', 'Lower as far as your form allows and stand at a steady tempo without bouncing.', 'Don''t let your heels rise or your back round at the bottom.', 'Train on a non-slip surface with clear space around you.']::text[], '{}'::text[], true),
  ('burpee', 'Burpee', 'Burpee', 'Full Body', 'Quads', array['Quads', 'Chest']::text[], array['Front Delts', 'Triceps', 'Abs', 'Glutes']::text[], 'bodyweight', 'squat', 'compound', 'bilateral', array['Stand with feet hip-width apart and arms relaxed.', 'Keep your body in line in the plank, hips neither sagging nor piked.', 'Squat, jump back to a plank, do a push-up, jump your feet to your hands, and jump up.', 'Don''t land stiff-legged or let your chest crash to the floor.', 'Land softly with bent knees and slow down if your form slips.']::text[], '{}'::text[], true),
  ('cable-bayesian-curl', 'Cable Bayesian Curl', 'Curl bayesiano en polea', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Face away from a low pulley, grab the handle, and step forward with your arm trailing behind you.', 'Keep your upper arm behind your torso and your chest open on every rep.', 'Curl all the way up without letting your arm drift forward, then return slowly to the stretch.', 'Don''t bring your elbow forward as you curl; you lose the stretch this exercise is built on.', 'Use a stable split stance so the cable can''t pull you off balance.']::text[], '{}'::text[], true),
  ('cable-crunch', 'Cable Crunch (Kneeling)', 'Crunch en polea (de rodillas)', 'Core', 'Abs', array['Abs']::text[], array['Obliques']::text[], 'cable', 'core', 'isolation', 'bilateral', array['Kneel facing a high pulley and hold the rope beside your head.', 'Keep your hips still and high; the movement should come from your spine.', 'Curl your torso down, bringing your elbows toward your thighs, then return against the cable.', 'Don''t sit back on your heels or pull the weight down with your arms.', 'Pick a weight that lets you flex your spine smoothly without jerking.']::text[], '{}'::text[], true),
  ('cable-curl-straight-bar', 'Cable Curl (Straight Bar)', 'Curl en polea (barra recta)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulley low, grab the straight bar palms-up, and stand close to the stack.', 'Keep your elbows at your sides, torso tall, and knees slightly bent.', 'Curl the bar to your chest, squeeze for a second, and lower against the cable''s pull.', 'Don''t stand too far from the pulley; the cable will pull your elbows forward.', 'Return the bar to the stack under control when you finish; don''t just let go.']::text[], '{}'::text[], true),
  ('cable-face-pull', 'Cable Face Pull (Rope)', 'Face pull en polea (cuerda)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back', 'Traps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Set the pulley at face height or slightly higher and grip the rope with palms facing down.', 'Keep your torso tall and stable, without leaning back.', 'Pull the rope to your face, splitting your hands apart and rotating your shoulders out at the end.', 'Don''t pull to your chest like a row; your hands should finish by your ears.', 'Use a moderate weight that lets you control the final rotation.']::text[], '{}'::text[], true),
  ('cable-fly-low-to-high', 'Cable Fly (Low to High)', 'Aperturas en polea (de abajo hacia arriba)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulleys at the lowest position and step forward between them.', 'Keep your torso upright, chest open, and elbows slightly bent.', 'Sweep your hands up in an arc to chin height, then lower slowly.', 'Don''t pull with your biceps or shrug your shoulders on the way up.', 'Grab and release the handles with the stack at rest so you don''t get pulled off balance.']::text[], '{}'::text[], true),
  ('cable-front-raise', 'Cable Front Raise', 'Elevaciones frontales en polea', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Upper Chest']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Stand facing away from a low pulley with the rope or bar between your legs.', 'Keep your torso upright and your arms nearly straight.', 'Raise the handle in front of you to shoulder height, then lower while resisting the cable.', 'Don''t let the cable pull you backward on the way down.', 'Take a wide enough stance to stay balanced against the cable''s pull.']::text[], '{}'::text[], true),
  ('cable-glute-kickback', 'Cable Glute Kickback', 'Patada de glúteo en polea', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Strap the ankle cuff to a low pulley and hold the frame with your torso leaning slightly forward.', 'Keep your pelvis still and your core tight as your leg moves back.', 'Kick your leg back and up by squeezing your glute, and return without the stack touching down.', 'Don''t arch your lower back to get your leg higher.', 'Check that the ankle cuff is securely fastened before you start.']::text[], '{}'::text[], true),
  ('cable-hip-abduction', 'Cable Hip Abduction', 'Abducción de cadera en polea', 'Glutes', 'Abductors', array['Abductors', 'Glutes']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Stand side-on to a low pulley with the ankle cuff on your far foot.', 'Keep your torso upright without leaning away from the working leg.', 'Sweep your leg out with your toes pointing forward and return while controlling the cable.', 'Don''t turn your toes up toward the ceiling; it shifts the work to other muscles.', 'Hold the machine with your near hand to stay balanced.']::text[], '{}'::text[], true),
  ('cable-hip-adduction', 'Cable Hip Adduction', 'Aducción de cadera en polea', 'Legs', 'Adductors', array['Adductors']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Stand side-on to a low pulley with the ankle cuff on the foot nearest the machine.', 'Keep your standing leg firm and your hips facing forward.', 'Sweep your leg across in front of your standing leg past the midline, then return slowly.', 'Don''t lean your torso to help pull the leg across.', 'Keep the load light; the adductors are easy to overload.']::text[], '{}'::text[], true),
  ('cable-lat-pulldown-underhand-grip', 'Cable Lat Pulldown (Underhand Grip)', 'Jalón al pecho en polea (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Biceps', 'Upper Back']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Grip a straight bar shoulder-width with palms facing you and lock your thighs under the pad.', 'Keep your chest up with a slight lean back, without over-arching your lower back.', 'Pull the bar to your lower chest with elbows tucked to your sides, then return under control.', 'Don''t turn it into a biceps curl: think about driving the elbows down, not bending the wrists.', 'Use a weight you can control on the way up without it lifting you off the seat.']::text[], '{}'::text[], true),
  ('cable-lateral-raise', 'Cable Lateral Raise (Single Arm)', 'Elevaciones laterales en polea (a una mano)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Set the pulley low and grab the handle with the hand farthest from the machine.', 'Keep your torso steady by holding the machine with your free hand.', 'Raise your arm out to the side to shoulder height, then lower while resisting the cable.', 'Don''t lean your trunk to cheat extra range of motion.', 'Start light: the cable keeps tension on the muscle through the whole rep.']::text[], '{}'::text[], true),
  ('cable-pallof-press', 'Cable Pallof Press', 'Press Pallof en polea', 'Core', 'Obliques', array['Obliques', 'Abs']::text[], '{}'::text[], 'cable', 'core', 'isolation', 'unilateral', array['Stand side-on to a chest-height pulley and hold the handle against your sternum.', 'Keep feet hip-width, knees soft, and shoulders square to the front.', 'Press your arms straight out while resisting the twist, hold two seconds, and return to your chest.', 'Don''t let your torso rotate toward the pulley as you press out.', 'Step away from the pulley only as far as you can resist rotation with good posture.']::text[], '{}'::text[], true),
  ('cable-pull-through', 'Cable Pull-Through', 'Pull-through en polea', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'cable', 'hinge', 'compound', 'bilateral', array['Face away from a low pulley with the rope between your legs and take two steps forward.', 'Keep your arms straight and your spine neutral as you push your hips back.', 'Let the rope travel between your legs, then extend your hips by squeezing your glutes.', 'Don''t pull the rope with your arms or turn it into a squat.', 'Finish standing tall without overextending your lower back at the top.']::text[], '{}'::text[], true),
  ('cable-rear-delt-fly', 'Cable Rear Delt Fly', 'Pájaros en polea', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulleys at shoulder height and cross the cables, holding each with the opposite hand.', 'Keep your arms nearly straight and your chest open.', 'Pull your arms back and out until they line up with your body, then return slowly.', 'Don''t bend your elbows and turn it into a row.', 'Take a stable step back before you start so you don''t lose your balance.']::text[], '{}'::text[], true),
  ('cable-rope-tricep-extensions', 'Cable Triceps Pushdown (Rope)', 'Extensión de tríceps en polea (cuerda)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulley high, grab the rope with palms facing each other, and bring your elbows to your sides.', 'Keep your chest up, a slight forward lean, and your elbows locked in beside your ribs.', 'Push down and spread the rope ends apart at the bottom, then return under control.', 'Don''t let your elbows flare or drift forward as the rope comes back up.', 'Keep your shoulders down and away from your ears to take strain off your neck.']::text[], '{}'::text[], true),
  ('cable-seated-row-underhand-grip', 'Cable Seated Row (Underhand Grip)', 'Remo sentado en polea (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Grip a straight bar shoulder-width with palms up and sit tall.', 'Keep your elbows tight to your body and your torso locked during the pull.', 'Row the bar to your navel driving your elbows back, then let it return until your arms are straight.', 'Don''t lift or flare your elbows; you''d lose the emphasis on the lats.', 'Keep your wrists straight and in line with your forearms throughout the set.']::text[], '{}'::text[], true),
  ('cable-shrug', 'Cable Shrug', 'Encogimientos en polea', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Attach a straight bar to the low pulley, grip it overhand and stand close to the stack.', 'Keep your arms straight and your torso vertical without leaning toward the pulley.', 'Shrug your shoulders toward your ears against the constant cable tension, then lower slowly.', 'Don''t bounce at the bottom; use the cable''s constant tension through the whole range.', 'Plant your feet firmly and stand close enough that the cable doesn''t pull you off balance.']::text[], '{}'::text[], true),
  ('cable-straight-arms-pull-downs', 'Cable Straight-Arm Pulldown', 'Jalón con brazos rectos en polea', 'Back', 'Lats', array['Lats']::text[], array['Triceps', 'Rear Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Face the high pulley with a straight bar or rope, arms extended and torso leaning slightly forward.', 'Keep your elbows nearly locked and your back neutral, hips pushed slightly back.', 'Sweep the bar down in an arc to your thighs squeezing your lats, then let it rise to eye level.', 'Don''t bend your elbows and turn it into a triceps pushdown.', 'Step back after grabbing the bar so the load doesn''t pull you forward at the start.']::text[], array['straight-bb-straight-arms-pull-downs']::text[], true),
  ('cable-triceps-kickback', 'Cable Triceps Kickback', 'Patada de tríceps en polea', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Set the pulley low, hold the cable bare or with a handle, and hinge your torso forward.', 'Keep your upper arm tight to your body and parallel to the floor with a flat back.', 'Extend your elbow back to lockout, then return slowly without losing tension.', 'Don''t move your shoulder or upper arm; only your forearm should move.', 'Brace your free hand on the machine to keep your back stable.']::text[], '{}'::text[], true),
  ('cable-triceps-pushdown-reverse-grip', 'Cable Triceps Pushdown (Reverse Grip)', 'Extensión de tríceps en polea (agarre supino)', 'Arms', 'Triceps', array['Triceps']::text[], array['Forearms']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulley high and grab the bar palms-up at shoulder width.', 'Keep your elbows by your torso and your wrists firm, not bent back.', 'Extend your elbows all the way down, squeeze your triceps, and return slowly to 90 degrees.', 'Don''t roll your shoulders forward to squeeze out the last reps.', 'Use less weight than with an overhand grip to avoid overloading your wrists.']::text[], '{}'::text[], true),
  ('cable-triceps-pushdown-single-arm', 'Cable Triceps Pushdown (Single-Arm)', 'Extensión de tríceps en polea (a una mano)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Set the pulley high with a single handle and hold it with your elbow tucked to your side.', 'Keep your shoulders level and your torso square to the pulley without twisting.', 'Extend your elbow fully, then return under control until your forearm passes parallel.', 'Don''t let your elbow drift away from your body or your shoulder roll forward.', 'Rest your free hand on the machine to stay balanced.']::text[], '{}'::text[], true),
  ('cable-triceps-pushdown-straight-bar', 'Cable Triceps Pushdown (Straight Bar)', 'Extensión de tríceps en polea (barra recta)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulley high and grab the straight bar overhand at shoulder width.', 'Keep your elbows pinned to your sides and your wrists in line with your forearms.', 'Push the bar down to full elbow extension, then let it rise to chest height.', 'Don''t let the bar come up past your chest or your elbows leave your sides.', 'Hold a stable stance with knees slightly bent so you don''t rock.']::text[], '{}'::text[], true),
  ('cable-upright-row', 'Cable Upright Row', 'Remo al mentón en polea', 'Shoulders', 'Side Delts', array['Side Delts']::text[], array['Traps', 'Front Delts']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Face a low pulley with a straight bar or rope, gripping slightly wider than your shoulders.', 'Keep your back straight and your shoulders relaxed at the start.', 'Raise your elbows out to shoulder height, then lower while resisting the cable.', 'Don''t lift your wrists higher than your elbows.', 'Use a moderate weight; the cable shouldn''t pull you forward.']::text[], '{}'::text[], true),
  ('cable-woodchop-high-to-low', 'Cable Woodchop (High to Low)', 'Leñador en polea (de arriba abajo)', 'Core', 'Obliques', array['Obliques']::text[], array['Abs', 'Front Delts']::text[], 'cable', 'core', 'compound', 'unilateral', array['Set the pulley high, stand side-on, and grip the handle with both hands above your shoulder.', 'Keep your arms nearly straight and rotate from your torso with your hips following.', 'Pull the handle diagonally toward the opposite knee, then control the rotation back.', 'Don''t pull with just your arms or bend your elbows to move the cable.', 'Pivot your back foot as you rotate to keep stress off your knee and lower back.']::text[], '{}'::text[], true),
  ('close-grip-bench-press', 'Barbell Bench Press (Close Grip)', 'Press de banca con barra (agarre cerrado)', 'Chest', 'Triceps', array['Triceps', 'Chest']::text[], array['Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Grip the bar with hands about shoulder-width apart, no narrower.', 'Keep your elbows tucked close to your body and wrists stacked over your forearms.', 'Lower the bar to your lower chest and lock out by driving through your triceps.', 'Don''t bring your hands too close: it loads your wrists without hitting the triceps any harder.', 'Set safety pins just below chest height if you train without a spotter.']::text[], array['close-grip-press']::text[], true),
  ('close-grip-decline-press', 'Barbell Bench Press (Decline, Close Grip)', 'Press de banca con barra (declinado, agarre cerrado)', 'Chest', 'Triceps', array['Triceps', 'Chest']::text[], array['Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Lock your feet under the decline bench rollers and grip the bar about shoulder-width apart.', 'Keep your elbows close to your torso and your head on the bench for the whole set.', 'Lower the bar to your lower chest and press up until your elbows are fully extended.', 'Don''t let your elbows flare out as you press.', 'Train with a spotter who can help you unrack and rerack the bar in this position.']::text[], '{}'::text[], true),
  ('close-grip-dips', 'Dip (Close Grip)', 'Fondos en paralelas (agarre cerrado)', 'Chest', 'Triceps', array['Triceps']::text[], array['Chest', 'Front Delts']::text[], 'bodyweight', 'push vertical', 'compound', 'bilateral', array['Support yourself on narrow parallel bars with arms locked out and body upright.', 'Keep your torso tall and elbows pointing back, tucked close to your sides.', 'Lower until your elbows reach about 90 degrees, then press back up to full extension.', 'Don''t let your shoulders shrug up toward your ears at the bottom.', 'Only go as deep as you can control without discomfort at the front of the shoulder.']::text[], '{}'::text[], true),
  ('crunch', 'Crunch', 'Crunch abdominal', 'Core', 'Abs', array['Abs']::text[], '{}'::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Lie on your back with knees bent, feet flat, and hands beside your temples.', 'Keep your neck neutral, with a fist''s width of space between chin and chest.', 'Lift your shoulders off the floor by contracting your abs, then lower slowly.', 'Don''t pull on your head with your hands to get up.', 'Exhale as you rise and don''t hold your breath during the set.']::text[], '{}'::text[], true),
  ('crunch-decline', 'Crunch (Decline)', 'Crunch abdominal (banco declinado)', 'Core', 'Abs', array['Abs']::text[], array['Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Hook your feet on the decline bench and hold a plate or dumbbell against your chest.', 'Keep your chin slightly tucked and your lower back close to the pad.', 'Curl your shoulders up until your abs are fully shortened, then lower until your shoulder blades touch.', 'Don''t sit all the way up; stop before your torso is upright so the abs stay loaded.', 'Add weight only when you can lower every rep slowly without straining your neck.']::text[], '{}'::text[], true),
  ('db-60-y-raises', 'Dumbbell Y-Raise (Incline)', 'Elevaciones en Y con mancuernas (banco inclinado)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], array['Rear Delts', 'Upper Back']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Lie face down on a steep incline bench, dumbbells hanging and thumbs pointing up.', 'Keep your chest on the bench and your neck neutral throughout.', 'Raise your arms in a Y shape in front of your head to ear height, then lower slowly.', 'Don''t shrug toward your ears or lift your chest off the bench.', 'Use light dumbbells: form breaks down quickly on this one when the load is too heavy.']::text[], '{}'::text[], true),
  ('db-curls-offset-grip', 'Dumbbell Curl (Incline, Offset Grip)', 'Curl con mancuernas (inclinado, agarre descentrado)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Lie back on an incline bench, arms hanging, with your pinky against the inner plate.', 'Keep your back and head on the bench and your arms hanging straight down behind your torso.', 'Curl while turning your palm up without letting the elbow drift forward, then lower to a full stretch.', 'Don''t peel your shoulders off the bench or bring your elbows forward as you curl.', 'Always lower under control; the biceps stretch in this position is intense.']::text[], '{}'::text[], true),
  ('db-oh-press-neutral-grip', 'Dumbbell Shoulder Press (Neutral Grip)', 'Press de hombros con mancuernas (agarre neutro)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Hold the dumbbells at shoulder height with your palms facing each other.', 'Keep your elbows in front of your body and your torso tight, without leaning back.', 'Press straight overhead, then lower under control to about chin level.', 'Don''t flare your elbows out; with a neutral grip they should stay in front.', 'Use a bench with back support if you find yourself swaying as you press.']::text[], array['neutral-grip-db-oh-press']::text[], true),
  ('db-press-neutral-grip', 'Dumbbell Bench Press (Incline, Neutral Grip)', 'Press de banca con mancuernas (inclinado, agarre neutro)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Lie on the incline bench with palms facing each other and the dumbbells over your chest.', 'Keep your elbows close to your torso and forearms vertical throughout the rep.', 'Lower until the dumbbells brush the sides of your chest, then press up under control.', 'Don''t rotate your wrists mid-rep; keep your palms facing each other the whole time.', 'Pick a weight you can control on the way down; if the dumbbells drift or wobble, go lighter.']::text[], '{}'::text[], true),
  ('db-pull-overs', 'Dumbbell Pullover', 'Pullover con mancuerna', 'Back', 'Lats', array['Lats']::text[], array['Chest', 'Triceps']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Lie on the bench holding one dumbbell with both hands over your chest, elbows slightly bent.', 'Keep your ribs down and your lower back stable, without arching as the weight lowers.', 'Arc the dumbbell behind your head until you feel a stretch, then bring it back over your chest.', 'Don''t bend and straighten your elbows each rep; keep the elbow angle fixed.', 'Cup the dumbbell under the top plate with interlocked hands so it can''t slip.']::text[], '{}'::text[], true),
  ('db-spider-hammer-curls', 'Dumbbell Spider Curl (Neutral Grip)', 'Curl araña con mancuernas (agarre neutro)', 'Arms', 'Biceps', array['Biceps', 'Forearms']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Lie chest-down on an incline bench with your arms hanging straight toward the floor.', 'Keep your upper arms perpendicular to the floor and your palms facing each other all set.', 'Curl without moving your elbows, squeeze for a second at the top, and lower slowly.', 'Don''t pull your elbows back or push them forward to gain range.', 'Plant your feet and chest firmly so the bench doesn''t shift during the set.']::text[], '{}'::text[], true),
  ('db-walking-lunges-long-steps', 'Dumbbell Lunge (Walking)', 'Zancada con mancuernas (caminando)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Hold a dumbbell in each hand at your sides and line up in a clear walkway.', 'Keep your torso tall and your front knee in line with your foot as you step.', 'Take a long step, lower until your back knee nearly touches the floor, then step through.', 'Don''t take short steps; they load the front knee and take work off the glutes.', 'Make sure your path is clear of obstacles before you start.']::text[], '{}'::text[], true),
  ('dead-bug', 'Dead Bug', 'Bicho muerto (dead bug)', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Lie on your back with arms reaching to the ceiling and hips and knees at 90 degrees.', 'Keep your lower back pressed into the floor for the entire exercise.', 'Slowly extend the opposite arm and leg, then return before switching sides.', 'Don''t let your lower back peel off the floor as your leg extends.', 'Shorten the leg reach if you can''t keep your back flat.']::text[], '{}'::text[], true),
  ('decline-bb-press', 'Barbell Bench Press (Decline)', 'Press de banca con barra (declinado)', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Hook your feet securely under the rollers before lying back on the decline bench.', 'Keep your shoulder blades squeezed together and your head on the bench throughout.', 'Lower the bar to your lower chest and press until your arms are straight without slamming into lockout.', 'Don''t bounce the bar off your sternum to get it moving.', 'Get a spotter to hand off and rerack: the decline angle makes it hard to rack the bar alone.']::text[], '{}'::text[], true),
  ('decline-dumbbell-fly', 'Dumbbell Fly (Decline)', 'Aperturas con mancuernas (declinado)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Secure your feet on the decline bench and press the dumbbells over your chest, palms facing in.', 'Keep a slight, fixed bend in your elbows for the entire set.', 'Open your arms in an arc until you feel a chest stretch, then bring them back together over your sternum.', 'Don''t lower the dumbbells below the level of the bench.', 'Start light: dumbbells are harder to control on a decline.']::text[], '{}'::text[], true),
  ('decline-sit-up', 'Sit-Up (Decline)', 'Abdominales (banco declinado)', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Hook your feet on the decline bench and lie back with your hands crossed on your chest.', 'Keep your chin slightly tucked and your neck relaxed.', 'Curl up one vertebra at a time, then lower slowly until you almost touch the bench.', 'Don''t pull on your head with your hands or throw yourself up with momentum.', 'Choose a decline you can control on the way down before adding weight.']::text[], '{}'::text[], true),
  ('dip', 'Dip', 'Fondos en paralelas', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'bodyweight', 'push vertical', 'compound', 'bilateral', array['Mount the parallel bars with arms locked out and legs slightly behind you.', 'Lean your torso slightly forward and keep your shoulders down, away from your ears.', 'Lower until your shoulders are level with your elbows, then press back to the top.', 'Don''t swing your legs to kip your way up.', 'Shorten the range or use assistance if you can''t control the bottom position.']::text[], '{}'::text[], true),
  ('dumbbell-arnold-press', 'Dumbbell Arnold Press', 'Press Arnold con mancuernas', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Sit with the dumbbells in front of your chin and palms facing you.', 'Keep your back on the pad and your elbows in front at the start.', 'Rotate your palms forward as you press up, and reverse the rotation as you lower.', 'Don''t split the rotation and the press into two separate movements.', 'Use less weight than on a standard press so you can control the rotation.']::text[], '{}'::text[], true),
  ('dumbbell-bench-press', 'Dumbbell Bench Press', 'Press de banca con mancuernas', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Sit with dumbbells on your thighs and kick them to your chest with your knees as you lie back.', 'Keep your shoulder blades together and forearms vertical over your elbows.', 'Lower the dumbbells to the sides of your chest and press up in a slight arc toward the middle.', 'Don''t let the dumbbells drift toward your head or feet as you lower them.', 'If you fail a rep, bring the dumbbells to your chest and sit up instead of dropping them out wide.']::text[], '{}'::text[], true),
  ('dumbbell-bench-press-decline', 'Dumbbell Bench Press (Decline)', 'Press de banca con mancuernas (declinado)', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Lock your feet on the decline bench with the dumbbells resting on your chest before lying back.', 'Keep your head on the bench and wrists firm, stacked over your elbows.', 'Lower the dumbbells toward your lower chest and press until your arms are nearly straight.', 'Don''t over-arch your back to grind the weight up.', 'Have a partner hand you the dumbbells if getting them into position on the decline is awkward.']::text[], '{}'::text[], true),
  ('dumbbell-bent-over-row', 'Dumbbell Bent-Over Row', 'Remo inclinado con mancuernas', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'dumbbell', 'pull horizontal', 'compound', 'bilateral', array['Hold a dumbbell in each hand, soften your knees and hinge your torso from the hips.', 'Keep your back neutral and your weight spread across your whole foot.', 'Row both dumbbells toward your waist with elbows close to your body, then lower them slowly.', 'Don''t let your head drop or your shoulders round forward on the way down.', 'If your lower back tires before your upper back, switch to the chest-supported version.']::text[], '{}'::text[], true),
  ('dumbbell-bulgarian-split-squat', 'Dumbbell Bulgarian Split Squat', 'Sentadilla búlgara con mancuernas', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Hamstrings']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Rest the top of your back foot on a bench and plant your front foot a long stride ahead.', 'Keep your hips square and your weight over the front foot.', 'Drop straight down until your front thigh is parallel, then stand up without bouncing.', 'Don''t push with your back leg; it''s only there for balance.', 'Set your distance from the bench before picking up weight so you don''t lose your balance.']::text[], '{}'::text[], true),
  ('dumbbell-chest-supported-row', 'Dumbbell Chest-Supported Row', 'Remo con mancuernas con apoyo de pecho', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Rear Delts', 'Biceps']::text[], 'dumbbell', 'pull horizontal', 'compound', 'bilateral', array['Lie face down on a bench inclined to about 30-45 degrees with a dumbbell in each hand.', 'Keep your chest on the pad and your toes planted on the floor so you don''t slide.', 'Row by driving your elbows back until your shoulder blades squeeze, then lower to straight arms.', 'Don''t crane your neck to look forward; keep your gaze toward the floor.', 'Set the dumbbells on the floor before getting up from the bench.']::text[], '{}'::text[], true),
  ('dumbbell-concentration-curl', 'Dumbbell Concentration Curl', 'Curl concentrado con mancuerna', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Sit on a bench with legs apart and brace your triceps against your inner thigh.', 'Keep your torso leaned forward and still, with your free hand on your other knee.', 'Curl the dumbbell toward your shoulder, turning your pinky up, then lower slowly.', 'Don''t use your leg or torso to push the dumbbell up.', 'Lower to just short of lockout without letting the weight drop at the end.']::text[], '{}'::text[], true),
  ('dumbbell-curl-incline', 'Dumbbell Curl (Incline)', 'Curl con mancuernas (inclinado)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Set the bench to about 45-60 degrees, lie back, and let your arms hang with palms forward.', 'Keep your shoulders against the pad and your elbows pointing at the floor.', 'Curl without letting your elbows drift forward, then lower until your biceps are fully stretched.', 'Don''t lift your head or shoulders off the bench as the set gets hard.', 'Start light; the stretched position puts a lot of load on the front of the shoulder.']::text[], '{}'::text[], true),
  ('dumbbell-farmers-carry', 'Dumbbell Farmer''s Carry', 'Paseo del granjero con mancuernas', 'Full Body', 'Forearms', array['Forearms', 'Traps']::text[], array['Abs', 'Obliques', 'Glutes']::text[], 'dumbbell', 'carry', 'compound', 'bilateral', array['Pick up a heavy dumbbell in each hand with a neutral spine and stand tall.', 'Keep your shoulders back, chest up, and eyes forward as you walk.', 'Walk the set distance with short, firm steps without stopping.', 'Don''t lean forward or let your shoulders round.', 'Clear your path of obstacles and set the weights down by bending your hips and knees.']::text[], '{}'::text[], true),
  ('dumbbell-farmers-hold', 'Dumbbell Farmer''s Hold', 'Sostén del granjero con mancuernas', 'Arms', 'Forearms', array['Forearms']::text[], array['Traps', 'Abs']::text[], 'dumbbell', 'carry', 'isolation', 'bilateral', array['Pick up two heavy dumbbells from the floor with a neutral spine and stand tall.', 'Keep your shoulders down and back, chest up, and arms straight at your sides.', 'Squeeze the handles hard and hold the position for the set time without moving.', 'Don''t shrug your shoulders or let the dumbbells swing.', 'When finished, lower the dumbbells by bending your hips and knees, not by rounding your back.']::text[], '{}'::text[], true),
  ('dumbbell-fly', 'Dumbbell Fly', 'Aperturas con mancuernas', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Lie on a flat bench with the dumbbells over your chest and palms facing each other.', 'Keep a slight, fixed bend in your elbows and your shoulder blades pinned together.', 'Open your arms in an arc to chest level, then close them as if hugging a tree.', 'Don''t go so heavy that you have to bend your elbows and turn it into a press.', 'Don''t let your arms drop below shoulder level.']::text[], '{}'::text[], true),
  ('dumbbell-fly-incline', 'Dumbbell Fly (Incline)', 'Aperturas con mancuernas (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Set the bench to a low incline and press the dumbbells up over your upper chest.', 'Keep your chest up and a slight, constant bend in your elbows.', 'Open your arms until you feel a stretch, then arc them back together over your collarbones.', 'Don''t let the dumbbells drift back toward your head instead of out to the sides.', 'Take extra care on the lowering phase; that''s where the shoulder is most exposed.']::text[], '{}'::text[], true),
  ('dumbbell-front-raise', 'Dumbbell Front Raise', 'Elevaciones frontales con mancuernas', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Upper Chest']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Stand with the dumbbells in front of your thighs and your palms facing you.', 'Keep your core braced and your elbows slightly bent.', 'Raise the dumbbells in front of you to shoulder height, then lower slowly.', 'Don''t lean back to heave the weight up.', 'Stop at eye level; going higher adds no useful work.']::text[], '{}'::text[], true),
  ('dumbbell-goblet-squat', 'Dumbbell Goblet Squat', 'Sentadilla goblet con mancuerna', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Abs']::text[], 'dumbbell', 'squat', 'compound', 'bilateral', array['Hold one dumbbell vertically against your chest, feet slightly wider than shoulder-width.', 'Keep the dumbbell tight to your chest and your torso tall as you descend.', 'Lower until your elbows brush the inside of your knees, then drive up through your heels.', 'Don''t let the dumbbell drift away from your body, which pulls your torso forward.', 'Pick a weight you can hold securely for the whole set without it slipping.']::text[], '{}'::text[], true),
  ('dumbbell-lateral-raise-seated', 'Dumbbell Lateral Raise (Seated)', 'Elevaciones laterales con mancuernas (sentado)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Sit on the end of a bench with the dumbbells at your sides and feet flat.', 'Keep your torso tall and your shoulders down, away from your ears.', 'Raise your arms out to the sides to shoulder height, then lower slowly.', 'Don''t rotate the dumbbells thumb-down as if pouring a jug of water.', 'Use a light weight that lets you pause briefly at the top.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-curtsy', 'Dumbbell Lunge (Curtsy)', 'Zancada con mancuerna (cruzada)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Quads', 'Adductors', 'Abductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Hold one dumbbell against your chest with your feet hip-width apart.', 'Keep your hips facing forward even as your back leg crosses behind you.', 'Cross one foot diagonally behind you, lower under control, then drive up through the front leg.', 'Don''t twist your torso or pelvis toward the crossing leg.', 'Shorten the crossover if you feel your balance slipping.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-forward', 'Dumbbell Lunge (Forward)', 'Zancada con mancuernas (hacia delante)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Stand with feet hip-width apart and a dumbbell in each hand.', 'Keep your chest up and your weight centered over the front foot as you land.', 'Step forward, lower under control, then push through your front heel to return.', 'Don''t slam down on your heel or land with your front foot too close.', 'Keep the load moderate; braking the forward step takes a lot of control.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-lateral', 'Dumbbell Lunge (Lateral)', 'Zancada con mancuerna (lateral)', 'Legs', 'Adductors', array['Adductors', 'Glutes']::text[], array['Quads']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Stand with your feet together, holding one dumbbell against your chest.', 'Keep the straight leg fully extended and your working foot flat on the floor.', 'Take a wide step to the side, sit your hips back over that leg, then push off to return.', 'Don''t let the bent knee drift far past your toes.', 'Widen your step gradually as your adductor mobility improves.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-reverse', 'Dumbbell Lunge (Reverse)', 'Zancada con mancuernas (hacia atrás)', 'Legs', 'Glutes', array['Glutes', 'Quads']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Stand with dumbbells at your sides and your weight on your standing foot.', 'Keep your front shin close to vertical and your torso leaning slightly forward.', 'Step one leg back, lower your knee near the floor, then drive through your front foot to return.', 'Don''t place your back foot on the same line as your front foot; it throws off your balance.', 'Lower your back knee gently and never bang it into the floor.']::text[], '{}'::text[], true),
  ('dumbbell-overhead-triceps-extension', 'Dumbbell Overhead Triceps Extension (Seated)', 'Extensión de tríceps sobre la cabeza con mancuerna (sentado)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Sit on a bench with back support and hold one dumbbell overhead with both hands.', 'Keep your back on the pad, ribs down, and elbows pointing forward.', 'Lower the dumbbell behind your head until you feel a stretch, then extend your elbows.', 'Don''t arch your lower back when the dumbbell is overhead.', 'Cup the top plate firmly with both palms so the dumbbell can''t slip.']::text[], '{}'::text[], true),
  ('dumbbell-overhead-triceps-extension-single-arm', 'Dumbbell Overhead Triceps Extension (Single-Arm)', 'Extensión de tríceps sobre la cabeza con mancuerna (a una mano)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Hold the dumbbell overhead with one arm extended, seated or standing with your abs braced.', 'Keep your elbow pointing at the ceiling and close to your head; your other hand can support it.', 'Lower the dumbbell behind your head by bending the elbow, then extend fully again.', 'Don''t let your elbow drift out or your torso lean to one side.', 'Work with a light weight you control; the dumbbell travels behind your head.']::text[], '{}'::text[], true),
  ('dumbbell-rear-delt-fly', 'Dumbbell Rear Delt Fly (Bent-Over)', 'Pájaros con mancuernas (inclinado)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Hinge at the hips with a flat back and let the dumbbells hang under your chest.', 'Keep your spine neutral and your neck in line with your torso.', 'Raise your arms out to the sides with a slight elbow bend, then lower slowly.', 'Don''t over-squeeze your shoulder blades; the movement should come from the shoulder.', 'If keeping your back flat is hard, rest your forehead on an incline bench.']::text[], '{}'::text[], true),
  ('dumbbell-rear-delt-fly-chest-supported', 'Dumbbell Rear Delt Fly (Chest-Supported)', 'Pájaros con mancuernas (pecho apoyado)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Lie face down on an incline bench with the dumbbells hanging and palms facing each other.', 'Keep your chest glued to the bench and your chin neutral.', 'Raise your arms out to the sides to shoulder level, then lower under control.', 'Don''t lift your chest off the bench to build momentum.', 'Use light dumbbells and put control ahead of load.']::text[], '{}'::text[], true),
  ('dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'Peso muerto rumano con mancuernas', 'Legs', 'Hamstrings', array['Hamstrings', 'Glutes']::text[], array['Lower Back', 'Forearms']::text[], 'dumbbell', 'hinge', 'compound', 'bilateral', array['Hold a dumbbell in each hand in front of your thighs with feet hip-width apart.', 'Keep the dumbbells close to your legs and your shoulders pulled back.', 'Push your hips back, lowering the dumbbells along your shins, then stand up squeezing your glutes.', 'Don''t let the dumbbells drift away from your body and hang forward.', 'Stop the descent as soon as your back starts to round.']::text[], '{}'::text[], true),
  ('dumbbell-romanian-deadlift-single-leg', 'Dumbbell Romanian Deadlift (Single-Leg)', 'Peso muerto rumano con mancuerna (a una pierna)', 'Glutes', 'Hamstrings', array['Hamstrings', 'Glutes']::text[], array['Lower Back', 'Abductors']::text[], 'dumbbell', 'hinge', 'compound', 'unilateral', array['Stand on one leg with a slight knee bend and hold the dumbbell in the opposite hand.', 'Keep your hips level and your free leg in line with your torso as you hinge.', 'Hinge until your torso is nearly parallel to the floor, then drive through your heel to stand.', 'Don''t let the hip of your back leg open up toward the ceiling.', 'Touch a wall or support with your free hand if you need more balance.']::text[], '{}'::text[], true),
  ('dumbbell-row-single-arm', 'Dumbbell Row (Single-Arm)', 'Remo con mancuerna (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Rear Delts', 'Biceps']::text[], 'dumbbell', 'pull horizontal', 'compound', 'unilateral', array['Place one knee and one hand on the bench, with the dumbbell hanging under the shoulder of your free arm.', 'Keep your back flat and parallel to the floor, with your shoulders level.', 'Pull the dumbbell toward your hip brushing your side, then lower until your lat stretches.', 'Don''t rotate your torso up on each rep to lift more weight.', 'Pick up and put down the dumbbell with a neutral back while supported on the bench.']::text[], '{}'::text[], true),
  ('dumbbell-shoulder-press', 'Dumbbell Shoulder Press (Seated)', 'Press de hombros con mancuernas (sentado)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Sit on a bench with a near-vertical back pad and bring the dumbbells to shoulder height.', 'Keep your back on the pad, core braced, and wrists stacked over your elbows.', 'Press the dumbbells up until they nearly touch, then lower to about ear level.', 'Don''t arch your lower back to peel off the pad.', 'Get the dumbbells to your shoulders by resting them on your knees first.']::text[], '{}'::text[], true),
  ('dumbbell-shoulder-press-standing', 'Dumbbell Shoulder Press (Standing)', 'Press de hombros con mancuernas (de pie)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps', 'Abs']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Stand with feet hip-width apart and the dumbbells resting at your shoulders.', 'Brace your abs and squeeze your glutes so your lower back doesn''t arch.', 'Press the dumbbells overhead, then lower under control to ear level.', 'Don''t drive the weight with your legs unless you''re doing a deliberate push press.', 'Go lighter than the seated version: standing demands more stability.']::text[], '{}'::text[], true),
  ('dumbbell-shrug', 'Dumbbell Shrug', 'Encogimientos con mancuernas', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Stand with a dumbbell at each side and your palms facing your body.', 'Keep your arms relaxed and straight, neck long and eyes forward.', 'Shrug your shoulders as high as possible, pause briefly at the top and lower until your traps stretch.', 'Don''t bend your elbows to help; your arms are just hooks.', 'Use straps if your grip gives out before your traps rather than dropping the dumbbells.']::text[], '{}'::text[], true),
  ('dumbbell-skull-crusher', 'Dumbbell Skull Crusher', 'Press francés con mancuernas', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Lie on a flat bench with a dumbbell in each hand, palms facing each other, arms extended.', 'Keep your upper arms fixed and parallel to each other throughout.', 'Lower the dumbbells beside your head by bending your elbows, then extend back to the top.', 'Don''t let the dumbbells drift apart or your elbows flare as you press up.', 'Lower slowly and keep a firm grip so you don''t hit your head.']::text[], '{}'::text[], true),
  ('dumbbell-skull-crusher-decline', 'Dumbbell Skull Crusher (Decline)', 'Press francés con mancuernas (banco declinado)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Hook your feet under the decline bench pad and press the dumbbells up over your chest, palms facing each other.', 'Keep your upper arms angled slightly back toward your head and still for the whole set.', 'Bend only at the elbows to lower the dumbbells beside your ears, then extend until your arms are straight.', 'Don''t let your elbows flare out or turn the rep into a press by moving your upper arms.', 'Hand the dumbbells off or bring them to your chest before sitting up; never sit up with arms extended.']::text[], '{}'::text[], true),
  ('dumbbell-split-squat', 'Dumbbell Split Squat', 'Sentadilla dividida con mancuernas', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Hamstrings']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Get into a staggered stance with both feet on the floor and dumbbells at your sides.', 'Keep your feet hip-width apart, as if standing on two rails.', 'Lower your back knee toward the floor without moving your feet, then return to the start.', 'Don''t let your front knee cave inward as you stand up.', 'Lower under control so your back knee doesn''t hit the floor.']::text[], '{}'::text[], true),
  ('dumbbell-standing-calf-raise-single-leg', 'Dumbbell Standing Calf Raise (Single-Leg)', 'Elevación de talón de pie con mancuerna (a una pierna)', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Stand on a step on one foot, dumbbell in the same-side hand and the other hand on a support.', 'Keep your working knee straight and your ankle aligned, without rolling outward.', 'Lower your heel below the step and rise as high as you can under control.', 'Don''t lean on your free hand to help yourself up.', 'Use a solid step and always hold on to something stable.']::text[], '{}'::text[], true),
  ('dumbbell-step-up', 'Dumbbell Step-Up', 'Subida al cajón con mancuernas', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Place your whole foot on a knee-height box with dumbbells at your sides.', 'Keep your torso leaning slightly forward and your working knee in line with your foot.', 'Step up using only the top leg, then lower slowly until your foot touches the floor.', 'Don''t push off the bottom leg to help yourself up.', 'Use a stable, non-slip box that can''t tip over.']::text[], '{}'::text[], true),
  ('dumbbell-suitcase-carry', 'Dumbbell Suitcase Carry', 'Paseo de maleta con mancuerna', 'Full Body', 'Obliques', array['Obliques', 'Forearms']::text[], array['Abs', 'Traps', 'Glutes']::text[], 'dumbbell', 'carry', 'compound', 'unilateral', array['Hold a single dumbbell at one side like a suitcase, arm straight.', 'Keep your shoulders level and torso upright without leaning toward the weight.', 'Walk the set distance at a controlled pace, then repeat on the other side.', 'Don''t compensate by leaning away from the dumbbell.', 'Start with a moderate weight; lateral stability is what you''re training.']::text[], '{}'::text[], true),
  ('dumbbell-sumo-squat', 'Dumbbell Sumo Squat', 'Sentadilla sumo con mancuerna', 'Legs', 'Adductors', array['Adductors', 'Glutes']::text[], array['Quads']::text[], 'dumbbell', 'squat', 'compound', 'bilateral', array['Set your feet well outside your shoulders, toes turned out, holding one dumbbell hanging down.', 'Keep your torso upright and push your knees out in line with your toes.', 'Lower the dumbbell between your legs, then stand by squeezing your glutes and inner thighs.', 'Don''t go so wide that your knees can''t follow your toes.', 'Stand on a step or plates if the dumbbell hits the floor before you reach full depth.']::text[], '{}'::text[], true),
  ('dumbbell-thruster', 'Dumbbell Thruster', 'Thruster con mancuernas', 'Full Body', 'Quads', array['Quads', 'Front Delts']::text[], array['Glutes', 'Triceps', 'Abs']::text[], 'dumbbell', 'squat', 'compound', 'bilateral', array['Hold the dumbbells at your shoulders, elbows forward, feet hip-width apart.', 'Keep your chest up and your torso braced through the squat.', 'Squat down, then drive up and use the leg drive to press the dumbbells overhead.', 'Don''t split the squat and press into two moves; it should be one continuous motion.', 'Lock out overhead with your ribs down so your lower back doesn''t arch.']::text[], '{}'::text[], true),
  ('dumbbell-triceps-kickback', 'Dumbbell Triceps Kickback', 'Patada de tríceps con mancuerna', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Place one hand and knee on the bench with a flat back and the dumbbell in your other hand.', 'Keep your upper arm parallel to the floor and your elbow tucked to your side all set.', 'Extend your elbow until your arm is straight, squeeze for a second, and return slowly.', 'Don''t let your elbow drop as you extend or swing the dumbbell with momentum.', 'Keep your spine neutral and don''t rotate your torso as your arm moves.']::text[], '{}'::text[], true),
  ('ez-bar-curl', 'EZ-Bar Curl', 'Curl con barra Z', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Grip the EZ-bar on the inner or outer bends with your palms angled slightly inward.', 'Keep your chest up and your elbows just in front of your ribs.', 'Curl until the bar nears your chest, then lower to just short of full extension.', 'Don''t shrug your shoulders or let your elbows ride up at the top.', 'Keep a neutral spine; don''t lean back to cheat the weight up.']::text[], '{}'::text[], true),
  ('ez-bar-overhead-triceps-extension', 'EZ-Bar Overhead Triceps Extension', 'Extensión de tríceps sobre la cabeza con barra Z', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Take a close grip on the EZ-bar and press it overhead with your arms extended.', 'Keep your elbows narrow and pointing forward, with your ribs down.', 'Lower the bar behind your head to a stretch, then extend without moving your upper arms.', 'Don''t compensate on the way up by arching your back or flaring your elbows.', 'Do it seated with back support if your lower back arches when standing.']::text[], '{}'::text[], true),
  ('ez-bar-pullover', 'EZ-Bar Pullover', 'Pullover con barra EZ', 'Back', 'Lats', array['Lats']::text[], array['Chest', 'Triceps']::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Lie on a flat bench with the EZ bar over your chest using a narrow overhand grip.', 'Keep your head down, feet planted and elbows slightly bent throughout the arc.', 'Lower the bar behind your head until you feel the stretch, then bring it back over your chest.', 'Don''t go past the point you can control or arch your back to chase more range.', 'Use a moderate load; the bar passes over your face and you must be able to stop it at any point.']::text[], '{}'::text[], true),
  ('ez-bar-skull-crusher', 'EZ-Bar Skull Crusher', 'Press francés con barra Z', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Lie on a flat bench holding the EZ-bar over your shoulders with arms extended.', 'Keep your elbows pointing at the ceiling, angled slightly back toward your head.', 'Lower the bar toward your forehead or behind your head by bending only your elbows, then press back up.', 'Don''t flare your elbows or let the movement turn into a press.', 'Use a spotter or a weight you fully control; the bar passes close to your face.']::text[], '{}'::text[], true),
  ('ez-bb-preacher-curls', 'EZ-Bar Preacher Curl', 'Curl predicador con barra Z', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Set the seat so your armpits sit snug against the top edge of the preacher pad.', 'Keep the backs of your upper arms pressed into the pad for the whole set.', 'Curl the EZ-bar until your biceps are fully contracted, then lower over 2-3 seconds to just short of lockout.', 'Don''t lift your elbows off the pad or roll your shoulders forward to finish the rep.', 'Never let the bar drop at the bottom; control the final stretch to spare your elbows.']::text[], '{}'::text[], true),
  ('ffe-db-split-squats', 'Dumbbell Split Squat (Front-Foot-Elevated)', 'Sentadilla dividida con mancuernas (pie delantero elevado)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Put your front foot on a plate or low step and set your back foot behind you.', 'Keep your torso upright and let your front knee travel forward over your foot.', 'Use the elevation to sink deep, then drive up through your front foot.', 'Don''t use a tall or wobbly platform that throws off your balance.', 'Check that the plate or step won''t slide before adding load.']::text[], '{}'::text[], true),
  ('glute-bridge', 'Glute Bridge', 'Puente de glúteo', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'bilateral', array['Lie on your back with knees bent and feet flat, hip-width apart.', 'Keep your pelvis slightly tucked and your core engaged as you lift.', 'Raise your hips by squeezing your glutes until your body forms a straight line, then lower slowly.', 'Don''t drive with your lower back instead of your glutes.', 'Do it on a mat to protect your spine from a hard floor.']::text[], '{}'::text[], true),
  ('glute-bridge-single-leg', 'Glute Bridge (Single-Leg)', 'Puente de glúteo (a una pierna)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'unilateral', array['Lie on your back with one foot planted near your glute and the other leg extended in the air.', 'Keep both hips at the same height throughout.', 'Drive your hips up through your working heel, pause, and lower without fully resting.', 'Don''t let the hip on your free-leg side sag as you lift.', 'Stop the set if your hamstring cramps, and bring your foot closer to your glute.']::text[], '{}'::text[], true),
  ('hack-squat-machine', 'Plate-Loaded Hack Squat', 'Sentadilla hack en máquina de discos', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Set your back and shoulders against the pads with your feet midway up the platform.', 'Keep your hips and lower back pressed into the pad through the full range.', 'Lower until your thighs pass parallel, then drive up without locking your knees at the top.', 'Don''t set your feet so high that you take the work off your quads.', 'Engage and release the safety handles only with your legs already extended.']::text[], array['hack-squats']::text[], true),
  ('hammer-curls', 'Dumbbell Hammer Curl', 'Curl martillo con mancuernas', 'Arms', 'Biceps', array['Biceps', 'Forearms']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Stand with dumbbells at your sides and your palms facing each other.', 'Keep your wrists straight and your elbows tucked against your body throughout.', 'Curl the dumbbell up to your shoulder like swinging a hammer, then lower over 2-3 seconds.', 'Don''t rotate your palm up or roll your shoulder forward as you curl.', 'Don''t swing your torso; if your posture breaks down, reduce the weight.']::text[], '{}'::text[], true),
  ('hanging-knee-raise', 'Hanging Knee Raise', 'Elevación de rodillas colgado', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Forearms']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Hang from a bar with a shoulder-width grip and your legs relaxed.', 'Keep your shoulders engaged and your body steady without swinging.', 'Bring your knees toward your chest while tilting your pelvis up, then lower slowly.', 'Don''t stop at knees to 90 degrees without curling your pelvis up.', 'Drop off the bar under control if your grip gives out before your abs do.']::text[], '{}'::text[], true),
  ('hanging-leg-raises-weighted', 'Hanging Leg Raise', 'Elevación de piernas colgado', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques', 'Forearms']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Hang from the bar with a firm grip, arms straight, and legs together.', 'Keep your shoulders engaged and your body still; kill any swing before you start.', 'Raise your straight legs while curling your pelvis up, then lower over 2-3 seconds.', 'Don''t use momentum from swinging to get your legs up.', 'If you can''t control the swing yet, start with hanging knee raises.']::text[], '{}'::text[], true),
  ('heels-elevated-hb-squats', 'Barbell Back Squat (High Bar, Heels Elevated)', 'Sentadilla trasera con barra (barra alta, talones elevados)', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Put your heels on a plate or wedge and rest the bar high on your traps.', 'Keep your torso as upright as possible and let your knees travel forward over your toes.', 'Sink deep and slow, then stand up without lifting your heels off the wedge.', 'Don''t use a wedge so tall that your weight shifts onto the balls of your feet.', 'Make sure the wedge is solid and won''t slide before you load the bar.']::text[], '{}'::text[], true),
  ('hex-bar-deadlift', 'Hex-Bar Deadlift', 'Peso muerto con barra hexagonal', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Lower Back', 'Traps', 'Forearms']::text[], 'hex-bar', 'hinge', 'compound', 'bilateral', array['Stand in the center of the hex bar with feet hip-width apart and grab the handles.', 'Keep your arms long, chest up, and spine neutral as you stand.', 'Push the floor away until you''re standing tall, then lower by bending hips and knees together.', 'Don''t stand off-center in the bar, which tips it forward or back.', 'Make sure the plates are secured with collars before you lift.']::text[], '{}'::text[], true),
  ('hex-bar-shrug', 'Hex-Bar Shrug', 'Encogimientos con barra hexagonal', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'hex-bar', 'isolation', 'isolation', 'bilateral', array['Step inside the hex bar, grab the high handles and lift it with your legs.', 'Keep your torso upright and your shoulders in line with the handles, without leaning.', 'Shrug your shoulders straight up, hold at the top and lower under control.', 'Don''t roll your shoulders forward; think about lifting them vertically toward your ears.', 'Pick up and set down the bar with a neutral back, just like a deadlift.']::text[], '{}'::text[], true),
  ('high-cable-fly', 'Cable Fly (High to Low)', 'Aperturas en polea (de arriba hacia abajo)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulleys at the highest position and stagger your feet for a stable base.', 'Lean your torso slightly forward and keep your chest open.', 'Sweep your hands down and in to hip height, then let them rise back slowly.', 'Don''t round your shoulders forward as your hands come together.', 'Use a weight that lets you control the return without the cables yanking your arms back.']::text[], '{}'::text[], true),
  ('hip-thrust-single-leg', 'Hip Thrust (Single-Leg)', 'Hip thrust (a una pierna)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'unilateral', array['Rest your upper back on a bench with one foot on the floor and the other knee pulled in.', 'Keep your pelvis level without letting it drop toward the free leg.', 'Drive through your working heel to full hip extension, then lower under control.', 'Don''t rotate your hips to gain height at the top.', 'Push the bench against a wall so it can''t slide.']::text[], '{}'::text[], true),
  ('hollow-body-hold', 'Hollow Body Hold', 'Posición hueca (hollow hold)', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Lie on your back with arms overhead and legs together and extended.', 'Keep your lower back pressed to the floor and your shoulders lifted.', 'Raise your arms and legs a few inches and hold the banana shape while breathing.', 'Don''t let your lower back arch as your legs lower.', 'Bend your knees or raise your legs higher if you can''t keep your lower back down.']::text[], '{}'::text[], true),
  ('hor-back-extensions-glutes-dominant', 'Back Extension (Horizontal, Glute Focus)', 'Hiperextensión (horizontal, enfoque glúteo)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Lower Back']::text[], 'bodyweight', 'hinge', 'compound', 'bilateral', array['Set the pad just below your hips so they can bend freely.', 'Keep your upper back slightly rounded and your eyes on the floor.', 'Lower by bending at the hips, then rise by squeezing your glutes until your body is in line.', 'Don''t arch your lower back past a straight line at the top.', 'Rise under control, without swinging that pulls on your lower back.']::text[], '{}'::text[], true),
  ('incline-barbell-bench-press', 'Barbell Bench Press (Incline)', 'Press de banca con barra (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Set the bench to a moderate incline and lie down with the bar roughly over your eyes.', 'Keep your shoulder blades pulled back and chest up without lifting your glutes off the seat.', 'Lower the bar to your upper chest, just below the collarbones, and press straight up.', 'Don''t set the incline too steep, or it turns into a shoulder press.', 'Unrack and rerack the bar with locked-out arms, never with bent elbows.']::text[], array['bb-press']::text[], true),
  ('incline-dumbbell-press', 'Dumbbell Bench Press (Incline)', 'Press de banca con mancuernas (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Sit on the incline bench with dumbbells on your thighs and kick them up with your knees as you lie back.', 'Keep your chest up and wrists straight, stacked directly over your elbows.', 'Lower the dumbbells beside your upper chest, then press up, bringing them slightly together at the top.', 'Don''t clank the dumbbells together or lose tension at the top.', 'When done, bring the dumbbells to your chest and sit up with them on your thighs instead of dropping them.']::text[], '{}'::text[], true),
  ('inverted-row', 'Inverted Row', 'Remo invertido', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Rear Delts', 'Biceps']::text[], 'bodyweight', 'pull horizontal', 'compound', 'bilateral', array['Set up under a bar fixed at hip height, grip it overhand and extend your body with heels on the floor.', 'Keep your body rigid like a plank, with glutes and abs squeezed.', 'Pull until your chest touches the bar squeezing your shoulder blades, then lower to straight arms.', 'Don''t let your hips sag or rise before your chest during the pull.', 'Make sure the rack or Smith machine bar is securely locked before hanging from it.']::text[], '{}'::text[], true),
  ('kettlebell-row-single-arm', 'Kettlebell Row (Single-Arm)', 'Remo con kettlebell (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Forearms']::text[], 'kettlebell', 'pull horizontal', 'compound', 'unilateral', array['Take a staggered stance, brace your free hand on a bench or thigh and grip the kettlebell handle.', 'Keep your torso hinged and stable, with your hips square to the floor.', 'Row the kettlebell toward your hip keeping your wrist straight, then lower under control.', 'Don''t let the kettlebell swing between reps; come to a stop at the bottom of each one.', 'Grip the handle firmly and make sure you have clear space around you as you row.']::text[], '{}'::text[], true),
  ('kettlebell-swing', 'Kettlebell Swing', 'Swing con kettlebell', 'Full Body', 'Glutes', array['Glutes', 'Hamstrings']::text[], array['Lower Back', 'Abs', 'Forearms']::text[], 'kettlebell', 'hinge', 'compound', 'bilateral', array['Stand with feet shoulder-width apart and the kettlebell a step in front of you.', 'Keep a neutral spine and hinge at the hips on every rep; this is not a squat.', 'Hike the bell between your legs and snap your hips through to send it to chest height.', 'Don''t lift the bell with your arms or lean back at the top.', 'Clear the space around you and park the kettlebell on the floor under control when done.']::text[], '{}'::text[], true),
  ('kettlebell-turkish-get-up', 'Kettlebell Turkish Get-Up', 'Levantamiento turco con kettlebell', 'Full Body', 'Abs', array['Abs', 'Front Delts']::text[], array['Obliques', 'Glutes', 'Triceps']::text[], 'kettlebell', 'core', 'compound', 'unilateral', array['Lie on your back holding the kettlebell in one hand, arm vertical, same-side knee bent.', 'Keep your arm locked and your eyes on the kettlebell throughout the get-up.', 'Rise in stages: elbow, hand, bridge, knee, stand; reverse the steps in order to come down.', 'Don''t rush the transitions or let your arm tilt off vertical.', 'Practice first with no weight or a shoe balanced on your fist before loading the kettlebell.']::text[], '{}'::text[], true),
  ('landmine-press', 'Landmine Press (Single Arm)', 'Press landmine (a una mano)', 'Shoulders', 'Front Delts', array['Front Delts', 'Upper Chest']::text[], array['Triceps', 'Abs']::text[], 'barbell', 'push vertical', 'compound', 'unilateral', array['Hold the end of the bar at shoulder height in one hand with the opposite foot forward.', 'Keep your trunk tight and your shoulders square to the front, without twisting.', 'Press the bar up and forward to full arm extension, then lower it under control to your shoulder.', 'Don''t lean away to the opposite side to press the bar.', 'Anchor the fixed end of the bar in a landmine unit or a secure corner.']::text[], '{}'::text[], true),
  ('lat-pulldown', 'Cable Lat Pulldown (Wide Grip)', 'Jalón al pecho en polea (agarre ancho)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Rear Delts']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Set the thigh pad snug over your legs and grip the bar overhand, wider than your shoulders.', 'Lean back a few degrees with your chest up and your lower back neutral.', 'Pull the bar to your upper chest by driving your elbows down, then let it rise until your lats stretch.', 'Don''t pull the bar behind your neck or rock your torso back to move more weight.', 'Return the bar to the top before standing up so the plates don''t slam.']::text[], '{}'::text[], true),
  ('lateral-raises-machine', 'Machine Lateral Raise', 'Elevaciones laterales en máquina', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Adjust the seat so the machine''s pivot lines up with your shoulder joints.', 'Rest your chest or back against the pad and keep your shoulders down.', 'Raise your arms out to the sides to shoulder height, then lower slowly.', 'Don''t shrug with your traps to get extra height.', 'Choose a weight you can lower under control without the plates slamming down.']::text[], '{}'::text[], true),
  ('leg-extensions-toes-dorsiflexed-neutral', 'Machine Leg Extension', 'Extensión de cuádriceps en máquina', 'Legs', 'Quads', array['Quads']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Line your knee up with the machine''s pivot and set the roller just above your ankle.', 'Keep your back against the pad and grip the handles so your hips stay down.', 'Extend all the way up, squeeze for a second, and lower the weight under control.', 'Don''t swing the weight up or let the roller drop.', 'Use moderate loads if your knees feel irritated, and see a professional if it hurts.']::text[], array['leg-extensions-toes-dorsiflexed-out']::text[], true),
  ('leg-press-calf-raises-toes-neutral', 'Plate-Loaded Leg Press Calf Raise', 'Elevación de talones en prensa de discos', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'plate-loaded', 'isolation', 'isolation', 'bilateral', array['Sit in the leg press with only the balls of your feet on the bottom edge of the platform.', 'Keep your knees nearly straight and locked in position for the whole set.', 'Press through the balls of your feet to full ankle extension, then return slowly to the stretch.', 'Don''t bend your knees to push the sled with your quads.', 'Keep the leg press safeties engaged in case your feet slip off the edge.']::text[], array['leg-press-calf-raises-neutral', 'calf']::text[], true),
  ('leg-press-quad-dominant', 'Plate-Loaded Leg Press', 'Prensa de piernas en máquina de discos', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Sit with your back and hips flat against the pad and your feet hip-width apart.', 'Keep your knees tracking over your toes throughout the descent.', 'Lower the sled under control to about 90 degrees of knee bend, then press through your whole foot.', 'Don''t let your hips peel off the seat at the bottom of the rep.', 'Don''t lock out your knees at the top, and release the safeties only with the sled under control.']::text[], '{}'::text[], true),
  ('low-cable-ropes-curls', 'Cable Hammer Curl (Rope)', 'Curl martillo en polea (cuerda)', 'Arms', 'Biceps', array['Biceps', 'Forearms']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulley low, grab the rope with palms facing each other, and take a step back.', 'Keep your elbows tucked to your torso and stand tall without leaning back.', 'Curl the rope to your chest, pulling the ends slightly apart, then lower under control.', 'Don''t let the cable drag your elbows forward on the way down.', 'Keep tension on the cable at the end of the set and don''t let the rope snap back.']::text[], '{}'::text[], true),
  ('lying-leg-raise', 'Lying Leg Raise', 'Elevación de piernas tumbado', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Lie on your back with legs straight and hands under your glutes or at your sides.', 'Keep your lower back in contact with the floor at all times.', 'Raise your legs to vertical, then lower them slowly without touching the floor.', 'Don''t arch your back as your legs approach the floor.', 'Bend your knees slightly if your lower back lifts off the floor.']::text[], '{}'::text[], true),
  ('machine-assisted-pull-up', 'Machine Assisted Pull-Up', 'Dominadas asistidas en máquina', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'machine', 'pull vertical', 'compound', 'bilateral', array['Set the counterweight, place your knees or feet on the platform and grab the top handles.', 'Keep your torso upright and your chest up without leaning onto the platform.', 'Pull until your chin passes the handles, then lower slowly until your arms are fully straight.', 'Don''t use so much assistance that the platform launches you; reduce it as you get stronger.', 'Keep both hands on the handles as you step on and off so the platform doesn''t jolt.']::text[], '{}'::text[], true),
  ('machine-chest-press-incline', 'Machine Chest Press (Incline)', 'Press de pecho en máquina (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'machine', 'push horizontal', 'compound', 'bilateral', array['Adjust the seat so the handles line up with your upper chest.', 'Keep your back and head against the pad and your chest open.', 'Press up and forward without locking your elbows, then return slowly to the start.', 'Don''t shrug your shoulders toward your ears as you press.', 'Check that the seat is locked in place before loading any weight.']::text[], '{}'::text[], true),
  ('machine-dip-assisted', 'Machine Dip (Assisted)', 'Fondos en máquina (asistidos)', 'Chest', 'Chest', array['Chest', 'Triceps']::text[], array['Front Delts']::text[], 'machine', 'push vertical', 'compound', 'bilateral', array['Select the counterweight, kneel on the pad, and grip the bars with your arms locked out.', 'Keep your torso slightly forward and your shoulders down and back.', 'Lower under control until your elbows reach about 90 degrees, then press to full extension.', 'Remember more counterweight means more help; don''t add it just to rep faster.', 'Step on and off the platform carefully, always holding onto the handles.']::text[], '{}'::text[], true),
  ('machine-donkey-calf-raise', 'Machine Donkey Calf Raise', 'Elevación de talones tipo burro en máquina', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Lean forward with your hips under the pad and your forearms on the support.', 'Keep your spine neutral and your hips bent and still for the whole set.', 'Lower your heels into a deep stretch and rise all the way onto your toes.', 'Don''t bend your knees to help yourself up.', 'Set the pad on your hips, never on your lower back.']::text[], '{}'::text[], true),
  ('machine-glute-kickback', 'Machine Glute Kickback', 'Patada de glúteo en máquina', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Rest your chest or forearms on the pad and place your foot on the platform or roller.', 'Keep your spine neutral and your standing hip fixed against the pad.', 'Push back until your hip is fully extended, then return slowly until you feel a stretch.', 'Don''t rotate your hip outward at the end of the kick.', 'Adjust the pad height so your working knee doesn''t hit the machine.']::text[], '{}'::text[], true),
  ('machine-hip-abduction', 'Machine Hip Abduction', 'Abducción de cadera en máquina', 'Glutes', 'Abductors', array['Abductors', 'Glutes']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Sit with your back against the pad and the pads on the outside of your knees.', 'Keep your hips planted on the seat and your torso still as you press out.', 'Open your legs to your full range, pause, and close them without letting the plates slam.', 'Don''t rock your torso back and forth to move more weight.', 'Set the starting width to match your mobility so you don''t force your hips.']::text[], '{}'::text[], true),
  ('machine-hip-adduction', 'Machine Hip Adduction', 'Aducción de cadera en máquina', 'Legs', 'Adductors', array['Adductors']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Sit with the pads on the inside of your knees and pick a comfortable starting width.', 'Keep your back supported and your pelvis stable on the seat.', 'Squeeze your legs until the pads meet, then open slowly, controlling the stretch.', 'Don''t let your legs fly open at the end of each rep.', 'Start with a narrow width and widen it gradually from set to set.']::text[], '{}'::text[], true),
  ('machine-hip-thrust', 'Machine Hip Thrust', 'Hip thrust en máquina', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Quads']::text[], 'machine', 'hinge', 'compound', 'bilateral', array['Set your back against the pad and position the belt or pad over your hips.', 'Keep your feet flat and your shins vertical at the top.', 'Drive your hips to full extension, squeeze for a second, and lower slowly.', 'Don''t push through your toes, which shifts the work to your quads.', 'Tighten the belt before loading so it doesn''t shift during the set.']::text[], '{}'::text[], true),
  ('machine-leg-extension-single-leg', 'Machine Leg Extension (Single-Leg)', 'Extensión de cuádriceps en máquina (a una pierna)', 'Legs', 'Quads', array['Quads']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Set the back pad and roller as for the two-leg version and load only one leg.', 'Keep the free leg relaxed and your hips pinned to the seat.', 'Fully extend your knee and lower slowly until the stack almost touches.', 'Don''t twist your torso toward the working side to move more weight.', 'Use a lighter load than the two-leg version so you don''t overload the knee.']::text[], '{}'::text[], true),
  ('machine-preacher-curl', 'Machine Preacher Curl', 'Curl predicador en máquina', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Adjust the seat so your elbow lines up with the machine''s pivot point.', 'Keep your arms on the pad and your chest in contact with the support.', 'Curl the handles to a full contraction and lower over 2-3 seconds without losing tension.', 'Don''t lift your hips off the seat to grind out the last reps.', 'Don''t let the weight stack slam at the bottom; control your elbow extension.']::text[], '{}'::text[], true),
  ('machine-pullover', 'Machine Pullover', 'Pullover en máquina', 'Back', 'Lats', array['Lats']::text[], array['Triceps', 'Chest']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Set the seat so your shoulders line up with the machine''s pivot and rest your elbows on the pads.', 'Keep your back against the pad and fasten the seat belt if the machine has one.', 'Drive your elbows down in an arc to your sides, then return slowly until your lats stretch.', 'Don''t pull with your hands; press through the back of your upper arms.', 'Align the pivot carefully; poor alignment loads the shoulder instead of the lats.']::text[], '{}'::text[], true),
  ('machine-reverse-hyperextension', 'Machine Reverse Hyperextension', 'Hiperextensión inversa en máquina', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Lower Back']::text[], 'machine', 'hinge', 'compound', 'bilateral', array['Lie face down with your hips at the bench edge and your ankles under the roller or strap.', 'Keep your torso flat on the bench and grip the handles firmly.', 'Raise your legs to body level using your glutes and lower them under control.', 'Don''t swing your legs with momentum to get them higher.', 'Don''t raise your legs past horizontal, to avoid overarching your lower back.']::text[], '{}'::text[], true),
  ('machine-seated-calf-raise', 'Machine Seated Calf Raise', 'Elevación de talones sentado en máquina', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Sit with the pad across your lower thighs and the balls of your feet on the platform.', 'Keep your torso upright and your knees bent at 90 degrees the whole time.', 'Drop your heels as low as they go, pause, and rise to a full contraction.', 'Don''t heave with your torso or arms to move the lever.', 'Release the safety only once the pad is snug on your thighs.']::text[], '{}'::text[], true),
  ('machine-seated-leg-curl-single-leg', 'Machine Seated Leg Curl (Single-Leg)', 'Curl femoral sentado en máquina (a una pierna)', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Set the machine as for the two-leg version and place just one leg on the roller.', 'Keep both thighs held down by the top pad and your hips still.', 'Curl your knee as far as it goes, pause briefly, and return slowly to almost straight.', 'Don''t rotate your leg in or out to help the weight move.', 'Pick a lighter load and make up for it with extra control on the way down.']::text[], '{}'::text[], true),
  ('machine-seated-leg-press', 'Machine Seated Leg Press', 'Prensa de piernas sentado en máquina', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'machine', 'squat', 'compound', 'bilateral', array['Set the seat so your knees start at about 90 degrees with your feet flat on the platform.', 'Keep your back against the pad and hold the side handles to stay stable.', 'Press smoothly until your legs are almost straight, then return without dropping the stack.', 'Don''t set the seat so close that your hips tuck under at the start.', 'Don''t lock your knees at the top, and set the stack down gently when you finish.']::text[], '{}'::text[], true),
  ('machine-standing-leg-curl', 'Machine Standing Leg Curl', 'Curl femoral de pie en máquina', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Rest your thigh on the pad and set the roller behind the ankle of your working leg.', 'Keep your hips against the pad and your torso still by holding the handles.', 'Curl your heel toward your glute and lower slowly without letting the weight drop.', 'Don''t arch your lower back to get your heel higher.', 'Adjust the pad height so your knee lines up with the machine''s pivot.']::text[], '{}'::text[], true),
  ('machine-triceps-extension', 'Machine Triceps Extension', 'Extensión de tríceps en máquina', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Adjust the seat so your elbows line up with the machine''s pivot and rest your arms on the pad.', 'Keep your back against the pad and your shoulders down throughout the set.', 'Extend your elbows fully, squeeze your triceps, and return slowly into flexion.', 'Don''t lift your elbows off the pad to push with your shoulders.', 'Don''t let the stack slam on the way back; control the entire eccentric.']::text[], '{}'::text[], true),
  ('mid-cable-fly', 'Cable Fly (Mid Height)', 'Aperturas en polea (altura media)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulleys at chest height and step forward into a staggered stance.', 'Keep a slight, fixed bend in your elbows and your torso steady, with no rocking.', 'Bring your hands together in front of your chest in a wide arc, then return under control to a stretch.', 'Don''t turn the fly into a press by bending and straightening your elbows.', 'Don''t let your arms travel behind your body line if you feel strain in the shoulder.']::text[], '{}'::text[], true),
  ('mountain-climber', 'Mountain Climber', 'Escaladores', 'Core', 'Abs', array['Abs', 'Hip Flexors']::text[], array['Front Delts', 'Quads']::text[], 'bodyweight', 'core', 'compound', 'bilateral', array['Start in a high plank with hands under shoulders and your body in a straight line.', 'Keep your hips low and stable as you alternate legs.', 'Drive one knee toward your chest and switch legs at a steady rhythm.', 'Don''t let your hips pike up as you speed up.', 'Slow down if your shoulders start drifting off your hands.']::text[], '{}'::text[], true),
  ('neutral-grip-lat-pulldown', 'Cable Lat Pulldown (Neutral Grip)', 'Jalón al pecho en polea (agarre neutro)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Attach a neutral-grip handle, sit with your thighs under the pad and your arms fully extended.', 'Keep your chest up and your elbows close to your body, pointing at the floor.', 'Pull the handle to your sternum by driving your elbows to your sides, then return slowly to full extension.', 'Don''t round your back at the end of the pull to bring the handle closer to your chest.', 'Make sure the carabiner on the handle is fully closed before loading the stack.']::text[], '{}'::text[], true),
  ('neutral-grip-pin-loaded-shoulder-press', 'Machine Shoulder Press (Neutral Grip)', 'Press de hombros en máquina (agarre neutro)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'machine', 'push vertical', 'compound', 'bilateral', array['Adjust the seat so the neutral handles sit at shoulder height.', 'Keep your back and head on the pad with your elbows slightly in front of your body.', 'Press up without locking your elbows, then lower slowly to shoulder height.', 'Don''t let the weight stack rest between reps.', 'Check the seat height: starting too low puts your shoulder in a strained position.']::text[], '{}'::text[], true),
  ('neutral-grip-supp-rows', 'Machine Chest-Supported Row (Neutral Grip)', 'Remo con apoyo de pecho en máquina (agarre neutro)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Biceps', 'Rear Delts']::text[], 'machine', 'pull horizontal', 'compound', 'bilateral', array['Sit with your chest against the pad and grab the vertical handles with palms facing each other.', 'Keep your back neutral and your elbows close to your body throughout the row.', 'Pull until your elbows are behind your torso, then straighten your arms without losing tension.', 'Don''t shrug your shoulders or jut your head forward at the end of the pull.', 'Let the weight return to rest under control when you finish the set.']::text[], '{}'::text[], true),
  ('neutral-grip-weighted-chin-ups', 'Pull-Up (Neutral Grip)', 'Dominadas (agarre neutro)', 'Back', 'Lats', array['Lats']::text[], array['Biceps', 'Upper Back', 'Forearms']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Hang from the parallel handles with your palms facing each other and your arms fully extended.', 'Keep your ribs down and lean your torso back slightly as you pull up.', 'Pull with your elbows tight to your body until your chin clears the handles, then lower without rushing.', 'Don''t shrug at the start; depress your shoulder blades before you bend your elbows.', 'If you add weight, secure the belt or dumbbell so it doesn''t swing between your legs.']::text[], '{}'::text[], true),
  ('nordic-hamstring-curl', 'Nordic Hamstring Curl', 'Curl nórdico de isquiotibiales', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Glutes', 'Calves']::text[], 'bodyweight', 'isolation', 'isolation', 'bilateral', array['Kneel on a mat with your ankles locked under a pad or held down by a partner.', 'Keep a straight line from knees to head, with glutes and abs tight.', 'Lower yourself forward as slowly as possible and use your hands to push back up if needed.', 'Don''t bend at the hips to shorten the lever as you lower.', 'Keep your hands ready to catch yourself and build the range gradually.']::text[], '{}'::text[], true),
  ('pec-deck-fly', 'Pec Deck Fly', 'Aperturas en máquina (pec deck)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Adjust the seat so the handles are at chest height with your elbows nearly straight.', 'Keep your back against the pad and shoulder blades together for the whole set.', 'Bring the handles together in front of your chest, squeeze for a second, and open under control.', 'Don''t let your arms swing too far back on the stretch when the weight is heavy.', 'Set the machine''s range-of-motion stop to limit how far back your arms go if needed.']::text[], '{}'::text[], true),
  ('plank', 'Plank', 'Plancha', 'Core', 'Abs', array['Abs']::text[], array['Obliques', 'Front Delts', 'Glutes']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Set your forearms down with elbows under shoulders and extend your legs onto your toes.', 'Hold a straight line from head to heels with your glutes squeezed.', 'Hold the position, breathing steadily and pushing the floor away with your forearms.', 'Don''t let your hips sag or pike up toward the ceiling.', 'End the set once you lose alignment, even if the timer isn''t up.']::text[], '{}'::text[], true),
  ('plate-loaded-belt-squat', 'Plate-Loaded Belt Squat', 'Sentadilla con cinturón en máquina de discos', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Fasten the belt around your hips and set your feet shoulder-width on the platform.', 'Keep your torso tall and hold the handles only for balance, not to pull yourself up.', 'Sink straight down to your target depth and stand by extending hips and knees together.', 'Don''t let the belt ride up to your waist; it should sit on your hips.', 'Check that the chain and carabiner are securely closed before adding weight.']::text[], '{}'::text[], true),
  ('plate-loaded-chest-press-incline', 'Plate-Loaded Chest Press (Incline)', 'Press de pecho en máquina de discos (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'plate-loaded', 'push horizontal', 'compound', 'bilateral', array['Sit with the handles at upper-chest height and your feet flat on the floor.', 'Keep your shoulder blades together and your back pressed into the pad.', 'Press the machine arms up, then lower under control until you feel a stretch.', 'Don''t lower so fast that the plates crash at the bottom of the rep.', 'Strip plates evenly from both sides so the machine doesn''t tip out of balance.']::text[], '{}'::text[], true),
  ('plate-loaded-chest-press-wide-grip', 'Plate-Loaded Chest Press (Wide Grip)', 'Press de pecho en máquina de discos (agarre ancho)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts', 'Triceps']::text[], 'plate-loaded', 'push horizontal', 'compound', 'bilateral', array['Adjust the seat so the wide handles line up with your mid-chest.', 'Keep your back and head against the pad with your shoulder blades pinned back.', 'Press the handles forward without locking your elbows, then return slowly until you feel a stretch.', 'Don''t let your shoulders roll off the pad at the end of the press.', 'Load and unload plates evenly on both sides of the machine.']::text[], '{}'::text[], true),
  ('plate-loaded-high-row', 'Plate-Loaded High Row', 'Remo alto en máquina de discos', 'Back', 'Lats', array['Lats', 'Upper Back']::text[], array['Rear Delts', 'Biceps']::text[], 'plate-loaded', 'pull vertical', 'compound', 'bilateral', array['Lock your thighs under the pad and grab the high handles with your arms extended overhead.', 'Keep your chest up with a slight forward lean, without arching your lower back.', 'Pull the handles down and back to the sides of your chest, then return under control to the top.', 'Don''t let the weight lift you off the seat on the way up.', 'Adjust the thigh pad so you''re locked in before loading heavy plates.']::text[], '{}'::text[], true),
  ('plate-loaded-lat-pulldown', 'Plate-Loaded Lat Pulldown', 'Jalón al pecho en máquina de discos', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Rear Delts']::text[], 'plate-loaded', 'pull vertical', 'compound', 'bilateral', array['Load the plates evenly on both sides, lock your thighs under the pad and grab the handles.', 'Keep your chest up and your torso still throughout the movement.', 'Pull the handles to the sides of your chest, then let them rise slowly until your arms are straight.', 'Don''t let the handles fly up at the top; control the eccentric on every rep.', 'Load and unload plates with the machine at rest, alternating sides so it doesn''t tip out of balance.']::text[], '{}'::text[], true),
  ('plate-loaded-leg-press-single-leg', 'Plate-Loaded Leg Press (Single-Leg)', 'Prensa de piernas en máquina de discos (a una pierna)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'unilateral', array['Place one foot in the middle of the platform and rest the other on the floor or frame.', 'Keep your pelvis level and your working knee in line with your second toe.', 'Lower slowly as far as your hips stay down, then press until your leg is almost straight.', 'Don''t let your knee collapse inward as you press.', 'Start light and keep the safeties within reach until your balance is solid.']::text[], '{}'::text[], true),
  ('plate-loaded-low-row', 'Plate-Loaded Low Row', 'Remo bajo en máquina de discos', 'Back', 'Lats', array['Lats', 'Upper Back']::text[], array['Biceps', 'Rear Delts']::text[], 'plate-loaded', 'pull horizontal', 'compound', 'bilateral', array['Set the seat so your chest is against the pad and grab the low handles with your arms extended.', 'Keep your chest on the pad and your torso upright without leaning back.', 'Row the handles toward your hips driving your elbows back, then return until your back stretches.', 'Don''t shorten the range; let your shoulder blades spread apart on every stretch.', 'Load plates evenly and strip them when you finish to leave the machine safe.']::text[], '{}'::text[], true),
  ('plate-loaded-pendulum-squat', 'Plate-Loaded Pendulum Squat', 'Sentadilla péndulo en máquina de discos', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Set your back and shoulders against the pads with your feet in the middle of the platform.', 'Keep your lower back pressed into the pad throughout the whole arc.', 'Sink deep, letting your knees travel forward, and drive up without fully locking out.', 'Don''t let your heels lift off the platform at the bottom.', 'Use the machine''s safety lock getting in and out so you never get stuck under the load.']::text[], '{}'::text[], true),
  ('plate-loaded-t-bar-row-chest-supported', 'Plate-Loaded T-Bar Row (Chest-Supported)', 'Remo en T en máquina de discos (con apoyo de pecho)', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps']::text[], 'plate-loaded', 'pull horizontal', 'compound', 'bilateral', array['Step onto the platform, rest your chest on the pad and grab the handles with straight arms.', 'Keep your chest on the pad and your neck neutral without lifting your head.', 'Row the handles toward your torso squeezing your shoulder blades, then lower the load under control.', 'Don''t peel your chest off the pad to push with your legs at the end of the pull.', 'Step on and off the platform only with the load in its resting position.']::text[], '{}'::text[], true),
  ('plate-loaded-wide-grip-shoulder-press-machine', 'Plate-Loaded Shoulder Press (Wide Grip)', 'Press de hombros en máquina de discos (agarre ancho)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'plate-loaded', 'push vertical', 'compound', 'bilateral', array['Set the seat so you start with the wide handles just above your shoulders.', 'Keep your back and head on the pad and your core engaged.', 'Press the machine arms up, then lower slowly until you feel a stretch in your shoulders.', 'Don''t arch your lower back to grind out the last reps.', 'Load plates evenly on both sides and strip them when you''re done.']::text[], '{}'::text[], true),
  ('prone-leg-curl-toes-dorsiflexed-neutral', 'Machine Lying Leg Curl', 'Curl femoral tumbado en máquina', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Lie face down with your knees just off the bench edge and the roller over your heels.', 'Keep your hips pressed into the bench and hold the handles throughout.', 'Curl your heels toward your glutes, then lower over two to three seconds.', 'Don''t lift your hips off the bench to finish the rep.', 'Don''t let the weight yank your knees straight at the bottom.']::text[], array['prone-leg-curls-toes-dorsiflexed-neutral', 'leg-curl']::text[], true),
  ('pull-up', 'Pull-Up', 'Dominadas', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Forearms']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Hang from the bar with an overhand grip slightly wider than your shoulders and your arms fully extended.', 'Keep your chest up, legs together and core braced so you don''t swing.', 'Pull your shoulder blades down first, then pull until your chin clears the bar; lower under control to a full hang.', 'Don''t kip with your legs or cut reps short with your elbows still bent at the bottom.', 'Lower yourself off the bar under control at the end of the set instead of dropping from the top.']::text[], '{}'::text[], true),
  ('pull-up-wide-grip', 'Pull-Up (Wide Grip)', 'Dominadas (agarre ancho)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Rear Delts', 'Biceps']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Grip the bar overhand about 1.5x shoulder width and hang with your arms straight.', 'Drive your chest toward the bar and keep your elbows pointing out and down.', 'Pull your elbows toward your ribs until your upper chest nears the bar, then lower over 2-3 seconds.', 'Don''t go so wide that you lose range of motion or your shoulders shrug up toward your ears.', 'Pick a grip width that lets you complete the full range without shoulder discomfort.']::text[], '{}'::text[], true),
  ('push-up', 'Push-Up', 'Flexiones', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts', 'Abs']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Place your hands slightly wider than your shoulders and extend your legs into a plank.', 'Keep a straight line from head to heels by squeezing your glutes and abs.', 'Lower your chest until it nearly touches the floor, then push back up to straight arms.', 'Don''t let your hips sag or pike up.', 'If you lose body position, drop to your knees or elevate your hands to finish the set.']::text[], '{}'::text[], true),
  ('push-up-close-grip', 'Push-Up (Close Grip)', 'Flexiones (agarre cerrado)', 'Chest', 'Triceps', array['Triceps', 'Chest']::text[], array['Front Delts']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Place your hands under your shoulders or slightly narrower, fingers pointing forward.', 'Keep your elbows tucked to your ribs and your body in a straight line.', 'Lower until your chest brushes your hands, then push up by straightening your elbows.', 'Don''t let your elbows flare out to the sides on the way down.', 'If your wrists feel loaded, widen your hands a little or use push-up handles.']::text[], '{}'::text[], true),
  ('push-up-decline', 'Push-Up (Decline)', 'Flexiones (declinadas)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Triceps', 'Front Delts', 'Abs']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Put your feet on a bench and your hands on the floor, slightly wider than your shoulders.', 'Brace your abs so your lower back doesn''t sag.', 'Lower your face and chest toward the floor under control, then push back up.', 'Don''t pike your hips up to shorten the range of motion.', 'Start with your feet only slightly elevated and raise them once your technique is solid.']::text[], '{}'::text[], true),
  ('push-up-incline', 'Push-Up (Incline)', 'Flexiones (inclinadas)', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Place your hands on a sturdy bench or box, slightly wider than your shoulders.', 'Keep your body straight as a board with your abs braced.', 'Bring your chest to the edge of the bench, then push back up to straight arms.', 'Don''t let your head reach the bench before your chest does.', 'Make sure the bench or box can''t slide before you put weight on it.']::text[], '{}'::text[], true),
  ('push-up-pike', 'Push-Up (Pike)', 'Flexiones (en pica)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Triceps', 'Upper Chest']::text[], 'bodyweight', 'push vertical', 'compound', 'bilateral', array['Place your hands and feet on the floor and lift your hips into an inverted V.', 'Keep your hips high and your back straight throughout.', 'Lower your head toward the floor between your hands, then push back up to straight arms.', 'Don''t drop your hips and turn it into a regular push-up.', 'Lower slowly and don''t put any weight on your head at the bottom.']::text[], '{}'::text[], true),
  ('reverse-crunch-decline', 'Reverse Crunch (Decline)', 'Crunch inverso (banco declinado)', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Lie head-up on a decline bench and grip the bench behind your head with knees bent at 90 degrees.', 'Keep your lower back pressed into the pad and your head resting on the bench.', 'Curl your hips up and toward your chest until they leave the pad, then lower them slowly.', 'Don''t swing your legs or use momentum to flip your hips up.', 'Start with a gentle decline and only steepen it once you can control every rep.']::text[], '{}'::text[], true),
  ('reverse-grip-chin-up-weighted', 'Chin-Up', 'Dominadas supinas', 'Back', 'Lats', array['Lats', 'Biceps']::text[], array['Upper Back', 'Forearms']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Grip the bar shoulder-width with palms facing you and hang with your arms straight.', 'Keep your torso steady and your elbows in front of your body, pointing at the floor.', 'Pull until your chin is over the bar, squeezing your lats, then lower all the way to a full hang.', 'Don''t stop halfway on the way down; reaching full extension trains the lats in their stretched position.', 'Add load gradually and keep every rep technically clean.']::text[], array['chin']::text[], true),
  ('reverse-grip-lats-machine', 'Machine Lat Pulldown (Underhand Grip)', 'Jalón en máquina (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Biceps', 'Upper Back']::text[], 'machine', 'pull vertical', 'compound', 'bilateral', array['Adjust the seat so you can reach the handles with arms extended and palms facing you.', 'Brace firmly against the chest or thigh pad and keep your back neutral.', 'Pull the handles down and back along the machine''s arc, then return slowly to a full stretch.', 'Don''t lift off the seat or pad to gain range with momentum.', 'Check that the weight pin is fully inserted before you start.']::text[], '{}'::text[], true),
  ('reverse-pec-deck-fly', 'Reverse Pec Deck Fly', 'Aperturas inversas en máquina (pec deck)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Sit facing the pad with the handles at shoulder height.', 'Keep your chest on the pad and your shoulders down for the whole set.', 'Sweep your arms back in an arc to your body line, then return under control.', 'Don''t pull with your traps by shrugging your shoulders.', 'Set the machine arms to the reverse position before you sit down.']::text[], '{}'::text[], true),
  ('romanian-deadlift', 'Barbell Romanian Deadlift', 'Peso muerto rumano con barra', 'Legs', 'Hamstrings', array['Hamstrings', 'Glutes']::text[], array['Lower Back', 'Forearms']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Start standing with the bar at hip height and a grip just outside your thighs.', 'Keep a soft, fixed bend in your knees and a neutral spine.', 'Push your hips back, sliding the bar down your legs until you feel the stretch, then stand up.', 'Don''t turn it into a squat by bending your knees more on the way down.', 'Only lower as far as your back stays neutral, even if you don''t reach mid-shin.']::text[], array['bb-rdl']::text[], true),
  ('rope-low-cable-oh-tricep-extensions', 'Cable Overhead Triceps Extension (Rope)', 'Extensión de tríceps sobre la cabeza en polea (cuerda)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Face away from the pulley, hold the rope behind your head, and stagger your feet.', 'Keep your elbows pointing forward and close to your head for the whole set.', 'Extend your elbows up and forward, then return slowly until you feel the stretch.', 'Don''t let your elbows flare out or your lower back arch.', 'Brace your abs to protect your lower back while the cable pulls you backward.']::text[], '{}'::text[], true),
  ('russian-twist', 'Russian Twist', 'Giro ruso', 'Core', 'Obliques', array['Obliques']::text[], array['Abs', 'Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Sit with knees bent, lean your torso back, and clasp your hands in front of your chest.', 'Keep your spine long and chest up without slouching.', 'Rotate side to side under control, bringing your hands beside each hip.', 'Don''t just move your arms; the twist should come from your ribcage.', 'Keep your heels on the floor if lifting your feet costs you your back position.']::text[], '{}'::text[], true),
  ('seated-cable-row', 'Cable Seated Row', 'Remo sentado en polea', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Biceps', 'Rear Delts']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Sit with your feet on the platform, knees slightly bent, holding the V-handle with arms extended.', 'Keep your torso upright and still, chest up and shoulders away from your ears.', 'Row the handle to your stomach squeezing your shoulder blades, then extend letting your shoulders reach forward.', 'Don''t rock your torso back and forth to move the weight with your lower back.', 'Grab and release the handle with your knees bent so you don''t yank on your lower back.']::text[], '{}'::text[], true),
  ('seated-leg-curl-toes-dorsiflexed-neutral', 'Machine Seated Leg Curl', 'Curl femoral sentado en máquina', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Set the back pad so your knee lines up with the pivot, and lower the thigh pad onto your legs.', 'Keep your back supported and lean slightly forward to stretch your hamstrings more.', 'Curl until your heels are under the seat, then return slowly to almost straight.', 'Don''t leave the thigh pad loose, or your hips will lift.', 'Set the lower roller snugly above your ankle so it doesn''t slide onto your calf.']::text[], array['seated-leg-curls-toes-dorsiflexed-neutral', 'seated-leg-curls-toes-dorsiflexed-out']::text[], true),
  ('side-plank', 'Side Plank', 'Plancha lateral', 'Core', 'Obliques', array['Obliques']::text[], array['Abs', 'Glutes', 'Abductors']::text[], 'bodyweight', 'core', 'isolation', 'unilateral', array['Lie on your side with your elbow under your shoulder and feet stacked or staggered.', 'Keep your hips, shoulders, and ankles in one straight line.', 'Lift your hips off the floor and hold without rotating your torso.', 'Don''t let your hips drop or shift backward.', 'Drop to your bottom knee if you can''t hold the line with straight legs.']::text[], '{}'::text[], true),
  ('single-arm-lat-pulldown', 'Cable Lat Pulldown (Single-Arm)', 'Jalón al pecho en polea (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull vertical', 'compound', 'unilateral', array['Sit under the high pulley with a single handle and your working arm fully stretched overhead.', 'Keep your torso square and stable, without twisting toward the working side.', 'Drive your elbow down toward your hip on a slight diagonal, then let the arm rise to stretch the lat.', 'Don''t compensate by leaning sideways; the movement should come from the shoulder and elbow.', 'Start with your weaker arm and match the reps on the other side.']::text[], '{}'::text[], true),
  ('single-db-preacher-curls', 'Dumbbell Preacher Curl (Single-Arm)', 'Curl predicador con mancuerna (a una mano)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Rest your whole triceps on the pad with your armpit over the edge and the dumbbell palm-up.', 'Keep your shoulder down and torso still; use your free hand on the pad for stability.', 'Curl all the way up without lifting your arm, then lower slowly to just short of full extension.', 'Don''t twist your torso or turn your wrist inward to finish the rep.', 'Pick a weight you can brake at the bottom; bouncing out of full extension loads the elbow hard.']::text[], '{}'::text[], true),
  ('single-hand-cable-unilateral-rows', 'Cable Seated Row (Single-Arm)', 'Remo sentado en polea (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'unilateral', array['Sit facing the pulley with a single handle and your arm extended forward.', 'Keep your shoulders level and torso stable, allowing only a slight rotation.', 'Row the handle toward your hip driving the elbow back, then extend letting your shoulder reach forward.', 'Don''t twist your whole torso to finish the rep; the work should come from your back.', 'Start with your weaker side and brace your free hand on your thigh for stability.']::text[], '{}'::text[], true),
  ('smith-machine-bench-press', 'Smith Machine Bench Press', 'Press de banca en máquina Smith', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'smith-machine', 'push horizontal', 'compound', 'bilateral', array['Position the bench so the bar comes down right on your lower chest.', 'Pinch your shoulder blades together and plant your feet firmly on the floor.', 'Twist to unrack, lower under control to your chest, and press straight up.', 'Don''t set the bench too far up or back: the bar should land on your chest, not your neck.', 'Set the Smith machine safety stops just above chest height before you start.']::text[], '{}'::text[], true),
  ('smith-machine-bench-press-incline', 'Smith Machine Bench Press (Incline)', 'Press de banca en máquina Smith (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'smith-machine', 'push horizontal', 'compound', 'bilateral', array['Position the incline bench so the bar travels down to your upper chest.', 'Keep your shoulder blades retracted and your glutes on the seat.', 'Lower the bar until it touches just below your collarbones, then press with steady force.', 'Don''t lift your back off the bench to move more weight.', 'Rotate the hooks to lock the bar in as soon as you finish your last rep.']::text[], '{}'::text[], true),
  ('smith-machine-bent-over-row', 'Smith Machine Bent-Over Row', 'Remo inclinado en máquina Smith', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps']::text[], 'smith-machine', 'pull horizontal', 'compound', 'bilateral', array['Set the safeties at knee height, grip the bar overhand and hinge your torso from the hips.', 'Position yourself so the bar travels straight to your stomach without hitting your thighs.', 'Row the bar to your navel squeezing your shoulder blades, then lower under control to straight arms.', 'Don''t stand too close or too far from the bar; the fixed path demands precise positioning.', 'Rotate the bar to re-rack it on the hooks before letting go at the end.']::text[], '{}'::text[], true),
  ('smith-machine-calf-raise', 'Smith Machine Calf Raise', 'Elevación de talones en máquina Smith', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'smith-machine', 'isolation', 'isolation', 'bilateral', array['Place a step under the bar and set the balls of your feet on its edge.', 'Keep your body vertical under the bar and your knees nearly straight.', 'Rise onto your toes, hold for a second, and lower into the stretch.', 'Don''t cut the range short by staying in the top half only.', 'Make sure the step can''t slide, and set the Smith machine safety stops.']::text[], '{}'::text[], true),
  ('smith-machine-hip-thrust', 'Smith Machine Hip Thrust', 'Hip thrust en máquina Smith', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Quads']::text[], 'smith-machine', 'hinge', 'compound', 'bilateral', array['Set a bench perpendicular to the Smith machine and place the padded bar in your hip crease.', 'Keep your gaze forward and your torso rigid going up and down.', 'Drive your hips up in line with shoulders and knees, then lower until you nearly touch the floor.', 'Don''t set your feet so far out that your hamstrings take over.', 'Rotate the bar to unhook it only once you''re set up properly underneath.']::text[], '{}'::text[], true),
  ('smith-machine-shoulder-press', 'Smith Machine Shoulder Press (Seated)', 'Press de hombros en máquina Smith (sentado)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'smith-machine', 'push vertical', 'compound', 'bilateral', array['Set an upright bench so the bar travels just in front of your face.', 'Keep your back on the pad and your wrists straight over your elbows.', 'Unrack the bar, lower it to your chin, and press up without locking out hard.', 'Don''t jut your head forward toward the bar as you lower it.', 'Set the Smith machine safety stops at shoulder height.']::text[], '{}'::text[], true),
  ('smith-machine-shrug', 'Smith Machine Shrug', 'Encogimientos en máquina Smith', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'smith-machine', 'isolation', 'isolation', 'bilateral', array['Set the safeties at mid-thigh, grip the bar overhand and unrack it by rotating your wrists.', 'Keep your body close to the bar and your back straight throughout.', 'Raise your shoulders along the bar''s path, squeeze at the top and lower through a full range.', 'Don''t cut the range short with excessive loads; range matters more than weight.', 'Set the safety stops just below the starting position before you begin.']::text[], '{}'::text[], true),
  ('smith-machine-split-squat', 'Smith Machine Split Squat', 'Sentadilla dividida en máquina Smith', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'smith-machine', 'lunge', 'compound', 'unilateral', array['Step under the bar in a split stance with your front foot slightly forward.', 'Keep your torso straight under the bar and your hips facing forward.', 'Drop straight down along the machine''s track and drive up with the front leg.', 'Don''t shorten your stance so much that your front heel lifts.', 'Set the safety stops just below the bottom of your rep.']::text[], '{}'::text[], true),
  ('smith-machine-squat', 'Smith Machine Squat', 'Sentadilla en máquina Smith', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'smith-machine', 'squat', 'compound', 'bilateral', array['Step under the bar with your feet slightly in front of the bar path.', 'Keep your back braced along the fixed bar path and your knees in line with your toes.', 'Lower under control to a depth you own, then stand up without snapping your knees locked.', 'Don''t place your feet directly under the bar; it overloads your knees.', 'Set the Smith machine safety stops and rotate the bar to rehook it when you finish.']::text[], '{}'::text[], true),
  ('standing-calf-raises-toes-neutral', 'Machine Standing Calf Raise', 'Elevación de talones de pie en máquina', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Set your shoulders under the pads and the balls of your feet on the edge of the step.', 'Keep your knees straight but not locked and your body tall.', 'Lower your heels into a stretch, pause, and rise all the way onto your toes.', 'Don''t bounce at the bottom and let tendon recoil do the work for your calves.', 'Plant the balls of your feet firmly on the step so they don''t slip off.']::text[], '{}'::text[], true),
  ('standing-db-lateral-raises', 'Dumbbell Lateral Raise (Standing)', 'Elevaciones laterales con mancuernas (de pie)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Stand with feet hip-width apart and the dumbbells at your sides.', 'Lean slightly forward and keep a soft bend in your elbows.', 'Raise the dumbbells out to shoulder height, then take 2-3 seconds to lower them.', 'Don''t swing your body to fling the dumbbells up.', 'Don''t raise your hands above shoulder height if you feel pinching or discomfort.']::text[], '{}'::text[], true),
  ('standing-db-offset-grip-curls', 'Dumbbell Curl (Standing, Offset Grip)', 'Curl con mancuernas (de pie, agarre descentrado)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Grip each dumbbell with your pinky against the inner plate so more weight sits on the thumb side.', 'Keep your elbows fixed at your sides and your wrists neutral, not bent back.', 'Curl while rotating your palm up all the way, then lower slowly as you resist the rotation.', 'Don''t relax the supination at the top; that extra twist is the whole point of the offset grip.', 'Go lighter than a regular curl; the offset grip puts more demand on your wrist.']::text[], '{}'::text[], true),
  ('standing-dumbbell-curl', 'Dumbbell Curl (Standing)', 'Curl con mancuernas (de pie)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Stand with feet hip-width apart, dumbbells at your sides, palms facing forward.', 'Keep your elbows pinned to your sides and your abs braced without leaning back.', 'Curl the dumbbells to shoulder height, then lower over 2-3 seconds to full extension.', 'Don''t swing your body or drive your elbows forward to borrow momentum.', 'If you have to swing to get the weight up, go lighter and keep the reps clean.']::text[], '{}'::text[], true),
  ('unilateral-supp-rows-reverse-grip', 'Machine Chest-Supported Row (Underhand Grip, Single-Arm)', 'Remo con apoyo de pecho en máquina (agarre supino, a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'machine', 'pull horizontal', 'compound', 'unilateral', array['Rest your chest on the pad and grab one handle palm up with your arm extended.', 'Keep your chest fixed and your shoulders square to the pad, without twisting your torso.', 'Drive your elbow back along your side toward your hip, then return slowly until your lat stretches.', 'Don''t push against the machine with your free hand to assist the pull.', 'Train both sides with the same load and reps to keep things balanced.']::text[], '{}'::text[], true),
  ('v-bb-cable-tricep-extensions', 'Cable Triceps Pushdown (V-Bar)', 'Extensión de tríceps en polea (barra V)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Set the pulley high, grab the V-bar, and start with your elbows bent at your sides.', 'Keep your wrists straight and your torso braced with a slight forward lean.', 'Extend to full lockout without snapping, then come up until your forearms pass parallel.', 'Don''t lean over the bar to push it down with your bodyweight.', 'Plant your feet firmly and apart so heavy loads don''t pull you off balance.']::text[], '{}'::text[], true),
  ('v-up', 'V-Up', 'Abdominales en V', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Lie on your back with your legs straight and your arms extended overhead.', 'Keep your legs together and your arms in line with your ears as you rise.', 'Lift your torso and legs together to touch your feet, then lower slowly without collapsing.', 'Don''t yank on your neck or bend your knees to reach the top.', 'Keep your lower back controlled on the way down; if it arches, shorten the range.']::text[], '{}'::text[], true),
  ('weighted-45-back-extensions', 'Back Extension (45°)', 'Hiperextensión (45°)', 'Glutes', 'Lower Back', array['Lower Back', 'Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'bilateral', array['Set the pad at hip height and lock your heels under the rollers.', 'Keep your spine neutral with arms crossed or the weight held against your chest.', 'Hinge down until you feel a stretch, then rise until your torso lines up with your legs.', 'Don''t go past a straight line by hard-arching your lower back at the top.', 'Add weight only once you can complete all reps with clean form.']::text[], '{}'::text[], true),
  ('wide-grip-cable-chest-pulls', 'Cable Pull to Chest (Wide Grip)', 'Jalón en polea al pecho (agarre ancho)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Rear Delts', 'Lats', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Face the pulley with a long bar at chest height and take a wide overhand grip.', 'Keep your torso upright and chest up, elbows at or slightly below shoulder height.', 'Pull the bar to your chest flaring your elbows and squeezing your shoulder blades; return to straight arms.', 'Don''t lean back to bring the bar closer; your torso shouldn''t move.', 'Set the pulley height and weight before starting so you can pull without neck tension.']::text[], '{}'::text[], true),
  ('wide-grip-cable-row', 'Cable Seated Row (Wide Grip)', 'Remo sentado en polea (agarre ancho)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Rear Delts', 'Lats', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Attach a long bar, grip it overhand wider than your shoulders and sit with your back upright.', 'Keep your elbows flared about 60-70 degrees from your torso and your chest up.', 'Row the bar to your lower chest squeezing your mid-back, then return slowly.', 'Don''t shrug at the end of the pull; finish with your shoulder blades, not your neck.', 'Choose a weight you can control on the return without it pulling you forward.']::text[], '{}'::text[], true),
  ('wide-grip-chest-press', 'Machine Chest Press (Wide Grip)', 'Press de pecho en máquina (agarre ancho)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts', 'Triceps']::text[], 'machine', 'push horizontal', 'compound', 'bilateral', array['Set the seat height so the wide handles sit level with your mid-chest.', 'Keep your back firmly against the pad and your chest up throughout.', 'Press until your arms are almost straight, then return slowly until your hands reach chest level.', 'Don''t let the weight stack touch down between reps; keep constant tension.', 'Make sure the weight pin is fully inserted before you start the set.']::text[], '{}'::text[], true),
  ('wide-grip-shoulder-press-machine', 'Machine Shoulder Press (Wide Grip)', 'Press de hombros en máquina (agarre ancho)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'machine', 'push vertical', 'compound', 'bilateral', array['Sit with the wide handles at ear height and your feet planted on the floor.', 'Keep your back against the pad and your wrists straight.', 'Press until your arms are nearly straight, then lower under control to the start.', 'Don''t shrug your shoulders up toward your ears as you press.', 'Secure the weight pin and seat adjustment before every set.']::text[], '{}'::text[], true),
  ('wide-grip-supp-seated-row', 'Machine Chest-Supported Row (Wide Grip)', 'Remo con apoyo de pecho en máquina (agarre ancho)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Rear Delts', 'Lats', 'Biceps']::text[], 'machine', 'pull horizontal', 'compound', 'bilateral', array['Adjust the seat and pad so the wide handles sit at chest height with your arms extended.', 'Keep your chest on the pad and your elbows flared out to the sides.', 'Row back until your elbows pass your torso, squeeze your shoulder blades and return under control.', 'Don''t pull your chest off the pad at the end of each rep to gain range.', 'Check the pin and seat height before every set.']::text[], '{}'::text[], true)
on conflict (id) do update set
  name_en = excluded.name_en,
  name_es = excluded.name_es,
  body_region = excluded.body_region,
  primary_muscle = excluded.primary_muscle,
  primary_muscles = excluded.primary_muscles,
  secondary_muscles = excluded.secondary_muscles,
  equipment = excluded.equipment,
  movement_pattern = excluded.movement_pattern,
  mechanic = excluded.mechanic,
  laterality = excluded.laterality,
  posture_tips = excluded.posture_tips,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();
